/*!
 * \file ai_infra_mhc_pre_split_post_res_tiling.h
 * \brief
 */

#ifndef AI_INFRA_MHC_PRE_SPLIT_POST_RES_TILING_H_
#define AI_INFRA_MHC_PRE_SPLIT_POST_RES_TILING_H_

#include "exe_graph/runtime/tiling_context.h"
#include "tiling/platform/platform_ascendc.h"
#include "register/op_def_registry.h"
#include "register/tilingdata_base.h"
#include "tiling/tiling_api.h"
#include "platform/platform_info.h"

namespace optiling {

// Tiling key 定义（constexpr，支持 optiling:: 命名空间限定访问）
// 单Tile模式：D<=2560，每token使用2个核心
constexpr uint64_t MHC_PRE_SPLIT_TILING_KEY_SINGLE_TILE = 0;
// 多Tile模式：D>2560，每token使用1个核心
constexpr uint64_t MHC_PRE_SPLIT_TILING_KEY_MULTI_TILE = 1;

// -----------算子TilingData定义（15个字段）---------------
BEGIN_TILING_DATA_DEF(AiInfraMhcPreSplitPostResTilingData)
TILING_DATA_FIELD_DEF(int64_t, totalLength);     // B*S 或 T，合轴后的token总数
TILING_DATA_FIELD_DEF(int64_t, N);               // 超连接维度 (固定4)
TILING_DATA_FIELD_DEF(int64_t, D);               // Dim维度 (2560/5120)
TILING_DATA_FIELD_DEF(int64_t, phiRows);         // N^2+N，phi的第一维
TILING_DATA_FIELD_DEF(int64_t, dimTile);         // 核内D的分块大小（对齐128元素）
TILING_DATA_FIELD_DEF(int64_t, dimLoop);         // D需要几个tile
TILING_DATA_FIELD_DEF(int64_t, coresPerToken);   // 每token使用的核数（1或2）
TILING_DATA_FIELD_DEF(int64_t, phiRowMid);       // 单核处理的phi行起始偏移（双核模式用）
TILING_DATA_FIELD_DEF(int64_t, blockDim);        // 实际启动的总核数
TILING_DATA_FIELD_DEF(int64_t, baseT);           // 每（组）核处理的token数（前coreTAct-1组）
TILING_DATA_FIELD_DEF(int64_t, tailT);           // 最后一（组）核处理的token数
TILING_DATA_FIELD_DEF(int64_t, coreTAct);        // T轴实际分组数
TILING_DATA_FIELD_DEF(float, normEps);           // RmsNorm epsilon
TILING_DATA_FIELD_DEF(int64_t, reduceWorkSize);  // ReduceSum work tensor大小（float元素数）
TILING_DATA_FIELD_DEF(float, invK);              // 1.0f/(N*D)，RmsNorm均值系数
END_TILING_DATA_DEF;

REGISTER_TILING_DATA_CLASS(AiInfraMhcPreSplitPostRes, AiInfraMhcPreSplitPostResTilingData)

// -----------算子CompileInfo定义-------------------
struct AiInfraMhcPreSplitPostResCompileInfo {
    int64_t coreNum = 0;
    int64_t ubSize = 0;
};

// -----------算子Tiling入参信息解析及Check类---------------
class AiInfraMhcPreSplitPostResInfoParser {
public:
    explicit AiInfraMhcPreSplitPostResInfoParser(gert::TilingContext *context) : context_(context)
    {}
    ~AiInfraMhcPreSplitPostResInfoParser() = default;

    ge::graphStatus GetOpName();
    ge::graphStatus GetNpuInfo();
    ge::graphStatus GetAttrInfo();
    ge::graphStatus CheckXValid();
    ge::graphStatus CheckPhiValid();
    ge::graphStatus CheckAlphaValid();
    ge::graphStatus CheckBiasValid();
    ge::graphStatus GenerateTiling();
    ge::graphStatus ParseAndCheck();

protected:
    gert::TilingContext  *context_     = nullptr;
    const char           *opName_      = nullptr;
    fe::PlatFormInfos    *platformInfo_ = nullptr;
    platform_ascendc::SocVersion socVersion_ = platform_ascendc::SocVersion::ASCEND910_93;

    // 硬件参数
    uint64_t coreNum_ = 0;
    uint64_t ubSize_  = 0;

    // 算子参数
    int64_t  totalLength_   = 0;   // 合轴后 T = B*S 或直接 T
    int64_t  N_             = 0;
    int64_t  D_             = 0;
    int64_t  phiRows_       = 0;   // N^2 + N
    int64_t  dimTile_       = 0;
    int64_t  dimLoop_       = 0;
    int64_t  coresPerToken_ = 0;
    int64_t  phiRowMid_     = 0;
    int64_t  blockDim_      = 0;
    int64_t  baseT_         = 0;
    int64_t  tailT_         = 0;
    int64_t  coreTAct_      = 0;
    int64_t  reduceWorkSize_  = 0;   // ReduceSum work tensor大小（float元素数）
    float    invK_            = 0.0f; // 1.0f/(N*D)

    float    normEps_     = 1e-6f;

    // tiling key
    uint64_t tilingKey_ = 0;
};

// ---------------算子Tiling类---------------
class AiInfraMhcPreSplitPostResTiling : public AiInfraMhcPreSplitPostResInfoParser {
public:
    explicit AiInfraMhcPreSplitPostResTiling(gert::TilingContext *context)
        : AiInfraMhcPreSplitPostResInfoParser(context)
    {}
    ~AiInfraMhcPreSplitPostResTiling() = default;
    ge::graphStatus DoTiling();

private:
    AiInfraMhcPreSplitPostResTilingData tilingData_;
};

}  // namespace optiling
#endif  // AI_INFRA_MHC_PRE_SPLIT_POST_RES_TILING_H_

