47	        op.Process();
48	    } else if (TILING_KEY_IS(TILING_KEY_MULTI_TILE)) {
49	        KERNEL_TASK_TYPE(TILING_KEY_MULTI_TILE, KERNEL_TYPE_AIV_ONLY);
50	        KernelMhcMultiTile<DTYPE_X> op;
51	        op.Init(x, phi, alpha, bias, h_post_out, h_res_out, usrWorkspace, &pipe, tilingData);
52	        op.Process();
53	    }
54	}
