*/

/*!
 * \file ai_infra_mhc_pre_split_post_res.cpp
 * \brief ai_infra_mhc_pre_split_post_res kernel 入口
 *
 * TILING_KEY_SINGLE_TILE (0)：D<=2560，dimLoop==1，双核/token
 *   → KernelMhcSingleTile<T>：无 dimLoop 循环
 *
 * TILING_KEY_MULTI_TILE  (1)：D>2560，dimLoop>1，单核/token
 *   → KernelMhcMultiTile<T>：分 tile 循环
 */

#include "ai_infra_mhc_pre_split_post_res_multi_tile.h"

using namespace AscendC;
using namespace AiInfraMhcPreSplitPostRes;

#define TILING_KEY_SINGLE_TILE 0
#define TILING_KEY_MULTI_TILE 1

extern "C" __global__ __aicore__ void ai_infra_mhc_pre_split_post_res(GM_ADDR x, GM_ADDR phi, GM_ADDR alpha,
    GM_ADDR bias, GM_ADDR h_post_out, GM_ADDR h_res_out, GM_ADDR workspace, GM_ADDR tiling)
{
    GET_TILING_DATA_WITH_STRUCT(AiInfraMhcPreSplitPostResTilingData, tilingDataIn, tiling);
    const AiInfraMhcPreSplitPostResTilingData *__restrict tilingData = &tilingDataIn;
    TPipe pipe;
    if (workspace == nullptr) {
        return;
    }
    GM_ADDR usrWorkspace = GetUserWorkspace(workspace);
    if (usrWorkspace == nullptr) {
        return;
    }
    if (TILING_KEY_IS(TILING_KEY_SINGLE_TILE)) {
        KERNEL_TASK_TYPE(TILING_KEY_SINGLE_TILE, KERNEL_TYPE_AIV_ONLY);
        KernelMhcSingleTile<DTYPE_X> op;
        op.Init(x, phi, alpha, bias, h_post_out, h_res_out, usrWorkspace, &pipe, tilingData);
        op.Process();
    } else if (TILING_KEY_IS(TILING_KEY_MULTI_TILE)) {
        KERNEL_TASK_TYPE(TILING_KEY_MULTI_TILE, KERNEL_TYPE_AIV_ONLY);
        KernelMhcMultiTile<DTYPE_X> op;
        op.Init(x, phi, alpha, bias, h_post_out, h_res_out, usrWorkspace, &pipe, tilingData);
        op.Process();
    }
}

