17	#include "log/log.h"
18	#include "err/ops_err.h"
19	
20	using namespace ge;
21	using namespace AscendC;
22	namespace optiling {
23	
24	// ------------------算子原型索引常量定义----------------
25	// Inputs Index
26	static constexpr int64_t MHC_X_INDEX = 0;
27	static constexpr int64_t MHC_PHI_INDEX = 1;
28	static constexpr int64_t MHC_ALPHA_INDEX = 2;
29	static constexpr int64_t MHC_BIAS_INDEX = 3;
30	
31	// Outputs Index
32	static constexpr int64_t MHC_H_POST_INDEX = 0;
33	static constexpr int64_t MHC_H_RES_INDEX = 1;
34	
35	// Attr Index
36	static constexpr int64_t MHC_NORM_EPS_INDEX = 0;
37	
38	// Dim Index
39	static constexpr int64_t MHC_DIM_ZERO = 0;
40	static constexpr int64_t MHC_DIM_ONE = 1;
41	static constexpr int64_t MHC_DIM_TWO = 2;
42	static constexpr int64_t MHC_DIM_THREE = 3;
43	
44	// Num constants
45	static constexpr int64_t MHC_NUM_ZERO = 0;
46	static constexpr int64_t MHC_NUM_ONE = 1;
47	static constexpr int64_t MHC_NUM_TWO = 2;
48	static constexpr int64_t MHC_NUM_THREE = 3;
49	static constexpr int64_t MHC_NUM_FOUR = 4;
50	
51	// 固定参数
52	static constexpr int64_t MHC_N_VALUE = 4;          // N 固定为4
53	static constexpr int64_t MHC_ALIGN_ELEM = 128;     // 256B / 2 (bf16/fp16)，D方向对齐粒度
54	static constexpr int64_t MHC_DIM_TILE_MAX = 2560;  // UB单次能处理的最大D大小
55	
56	// 入参限制
57	static constexpr int64_t MHC_MIN_T = 1;
58	static constexpr int64_t MHC_MAX_T = 512 * 1024;
59	// D 仅支持 2560 和 5120 两个值
60	static constexpr int64_t MHC_D_2560 = 2560;
61	static constexpr int64_t MHC_D_5120 = 5120;
62	
63	static constexpr int64_t MIN_FP32_ALIGN_ELEM_SIZE = 8;
64	
65	// --------------------------GetOpName-------------------------------------
66	ge::graphStatus AiInfraMhcPreSplitPostResInfoParser::GetOpName()
67	{
68	    if (context_->GetNodeName() == nullptr) {
69	        OP_LOGE("AiInfraMhcPreSplitPostRes", "opName got from TilingContext is nullptr");
70	        return ge::GRAPH_FAILED;
71	    }
72	    opName_ = context_->GetNodeName();
73	    return ge::GRAPH_SUCCESS;
74	}
75	
76	// --------------------------GetNpuInfo-------------------------------------
77	ge::graphStatus AiInfraMhcPreSplitPostResInfoParser::GetNpuInfo()
78	{
79	    platformInfo_ = context_->GetPlatformInfo();
80	    if (platformInfo_ == nullptr) {
81	        auto compileInfoPtr = context_->GetCompileInfo<AiInfraMhcPreSplitPostResCompileInfo>();
82	        OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(context_, "compile info is null"), return ge::GRAPH_FAILED);
83	        coreNum_ = compileInfoPtr->coreNum;
84	        ubSize_ = compileInfoPtr->ubSize;
85	        OP_LOGD(context_->GetNodeName(), "GetPlatformInfo: platformInfo == nullptr, using compileInfo");
86	        return ge::GRAPH_SUCCESS;
87	    }
88	
89	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo_);
90	    coreNum_ = ascendcPlatform.GetCoreNumAiv();
91	    uint32_t aicNum = ascendcPlatform.GetCoreNumAic();
92	    OP_CHECK_IF(aicNum == 0 || coreNum_ == 0, OP_LOGE(opName_, "num of core obtained is 0."), return GRAPH_FAILED);
93	
94	    uint64_t ubSizePlatForm;
95	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizePlatForm);
96	    ubSize_ = ubSizePlatForm;
97	
98	    socVersion_ = ascendcPlatform.GetSocVersion();
99	    if ((socVersion_ != platform_ascendc::SocVersion::ASCEND910B) &&
100	        (socVersion_ != platform_ascendc::SocVersion::ASCEND910_93)) {
101	        OP_LOGE(opName_, "SOC Version[%d] is not support.", (int32_t)socVersion_);
102	        return GRAPH_FAILED;
103	    }
104	
105	    OP_CHECK_IF(context_->GetWorkspaceSizes(1) == nullptr,
106	        OP_LOGE(opName_, "workSpaceSize got from ge is nullptr"),
107	        return ge::GRAPH_FAILED);
108	    OP_CHECK_IF(context_->GetRawTilingData() == nullptr,
109	        OP_LOGE(context_->GetNodeName(), "RawTilingData got from GE context is nullptr."),
110	        return ge::GRAPH_FAILED);
111	
112	    // workspace 大小在 GenerateTiling 中根据 blockDim/N/D 动态确定，此处仅做 nullptr 检查
113	
114	    return ge::GRAPH_SUCCESS;
115	}
116	
117	// --------------------------GetAttrInfo-------------------------------------
118	ge::graphStatus AiInfraMhcPreSplitPostResInfoParser::GetAttrInfo()
119	{
120	    auto attrsPtr = context_->GetAttrs();
121	    OP_CHECK_IF(
122	        attrsPtr == nullptr, OP_LOGE(context_->GetNodeName(), "GetAttrs() returned nullptr."), return ge::GRAPH_FAILED);
123	
124	    auto normEpsPtr = attrsPtr->GetFloat(MHC_NORM_EPS_INDEX);
125	    normEps_ = (normEpsPtr != nullptr ? *normEpsPtr : 1e-6f);
126	
127	    return ge::GRAPH_SUCCESS;
128	}
129	
130	// --------------------------CheckXValid-------------------------------------
131	ge::graphStatus AiInfraMhcPreSplitPostResInfoParser::CheckXValid()
132	{
133	    const gert::StorageShape *xShapePtr = context_->GetInputShape(MHC_X_INDEX);
134	    OP_CHECK_IF(
135	        xShapePtr == nullptr, OP_LOGE(context_->GetNodeName(), "x InputShape is nullptr."), return ge::GRAPH_FAILED);
136	
137	    int64_t xDimNum = static_cast<int64_t>(xShapePtr->GetOriginShape().GetDimNum());
138	    OP_CHECK_IF(xDimNum != MHC_NUM_THREE && xDimNum != MHC_NUM_FOUR,
139	        OP_LOGE(context_->GetNodeName(), "x: number of dimensions must be 3 (TND) or 4 (BSND)."),
140	        return ge::GRAPH_FAILED);
141	
142	    if (xDimNum == MHC_NUM_FOUR) {
143	        // BSND: [B, S, N, D]
144	        int64_t B = xShapePtr->GetOriginShape().GetDim(MHC_DIM_ZERO);
145	        int64_t S = xShapePtr->GetOriginShape().GetDim(MHC_DIM_ONE);
146	        N_ = xShapePtr->GetOriginShape().GetDim(MHC_DIM_TWO);
147	        D_ = xShapePtr->GetOriginShape().GetDim(MHC_DIM_THREE);
148	        totalLength_ = B * S;
149	    } else {
150	        // TND: [T, N, D]
151	        totalLength_ = xShapePtr->GetOriginShape().GetDim(MHC_DIM_ZERO);
152	        N_ = xShapePtr->GetOriginShape().GetDim(MHC_DIM_ONE);
153	        D_ = xShapePtr->GetOriginShape().GetDim(MHC_DIM_TWO);
154	    }
155	
156	    bool isValid = true;
157	    isValid = isValid && (totalLength_ >= MHC_MIN_T && totalLength_ <= MHC_MAX_T);
158	    isValid = isValid && (N_ == MHC_N_VALUE);
159	    isValid = isValid && (D_ == MHC_D_2560 || D_ == MHC_D_5120);
160	    OP_CHECK_IF(!isValid,
161	        OP_LOGE(context_->GetNodeName(),
162	            "x shape is invalid: T=%ld, N=%ld, D=%ld (D must be 2560 or 5120).",
163	            totalLength_,
164	            N_,
165	            D_),
166	        return ge::GRAPH_FAILED);
167	
168	    auto xDesc = context_->GetInputDesc(MHC_X_INDEX);
169	    OP_CHECK_IF(xDesc == nullptr, OP_LOGE(context_->GetNodeName(), "xDesc is nullptr."), return ge::GRAPH_FAILED);
170	    ge::DataType xDtype = xDesc->GetDataType();
171	    OP_CHECK_IF(xDtype != ge::DataType::DT_BF16 && xDtype != ge::DataType::DT_FLOAT16,
172	        OP_LOGE(context_->GetNodeName(), "x only supports bfloat16 and float16."),
173	        return ge::GRAPH_FAILED);
174	
175	    return ge::GRAPH_SUCCESS;
176	}
177	
178	// --------------------------CheckPhiValid-------------------------------------
179	ge::graphStatus AiInfraMhcPreSplitPostResInfoParser::CheckPhiValid()
180	{
181	    const gert::StorageShape *phiShapePtr = context_->GetInputShape(MHC_PHI_INDEX);
182	    OP_CHECK_IF(phiShapePtr == nullptr,
183	        OP_LOGE(context_->GetNodeName(), "phi InputShape is nullptr."),
184	        return ge::GRAPH_FAILED);
185	    OP_CHECK_IF(phiShapePtr->GetStorageShape().GetDimNum() != MHC_NUM_TWO,
186	        OP_LOGE(context_->GetNodeName(), "phi: number of dimensions must be 2."),
187	        return ge::GRAPH_FAILED);
188	
189	    // phi shape: [N^2+N, N*D]
190	    int64_t phiDim0 = phiShapePtr->GetStorageShape().GetDim(MHC_DIM_ZERO);
191	    int64_t phiDim1 = phiShapePtr->GetStorageShape().GetDim(MHC_DIM_ONE);
192	    phiRows_ = N_ * N_ + N_;
193	
194	    bool isValid = true;
195	    isValid = isValid && (phiDim0 == phiRows_);
196	    isValid = isValid && (phiDim1 == N_ * D_);
197	    OP_CHECK_IF(!isValid,
198	        OP_LOGE(context_->GetNodeName(),
199	            "phi shape invalid: expected [%ld, %ld], got [%ld, %ld].",
200	            phiRows_,
201	            N_ * D_,
202	            phiDim0,
203	            phiDim1),
204	        return ge::GRAPH_FAILED);
205	
206	    auto phiDesc = context_->GetInputDesc(MHC_PHI_INDEX);
207	    OP_CHECK_IF(phiDesc == nullptr, OP_LOGE(context_->GetNodeName(), "phiDesc is nullptr."), return ge::GRAPH_FAILED);
208	    OP_CHECK_IF(phiDesc->GetDataType() != ge::DataType::DT_FLOAT,
209	        OP_LOGE(context_->GetNodeName(), "phi dtype must be float32."),
210	        return ge::GRAPH_FAILED);
211	
212	    return ge::GRAPH_SUCCESS;
213	}
214	
215	// --------------------------CheckAlphaValid-------------------------------------
216	ge::graphStatus AiInfraMhcPreSplitPostResInfoParser::CheckAlphaValid()
217	{
218	    const gert::StorageShape *alphaShapePtr = context_->GetInputShape(MHC_ALPHA_INDEX);
219	    OP_CHECK_IF(alphaShapePtr == nullptr,
220	        OP_LOGE(context_->GetNodeName(), "alpha InputShape is nullptr."),
221	        return ge::GRAPH_FAILED);
222	    OP_CHECK_IF(alphaShapePtr->GetStorageShape().GetDimNum() != MHC_NUM_ONE,
223	        OP_LOGE(context_->GetNodeName(), "alpha: number of dimensions must be 1."),
224	        return ge::GRAPH_FAILED);
225	    OP_CHECK_IF(alphaShapePtr->GetStorageShape().GetDim(MHC_DIM_ZERO) != MHC_NUM_TWO,
226	        OP_LOGE(context_->GetNodeName(), "alpha shape must be [2]."),
227	        return ge::GRAPH_FAILED);
228	
229	    auto alphaDesc = context_->GetInputDesc(MHC_ALPHA_INDEX);
230	    OP_CHECK_IF(
231	        alphaDesc == nullptr, OP_LOGE(context_->GetNodeName(), "alphaDesc is nullptr."), return ge::GRAPH_FAILED);
232	    OP_CHECK_IF(alphaDesc->GetDataType() != ge::DataType::DT_FLOAT,
233	        OP_LOGE(context_->GetNodeName(), "alpha dtype must be float32."),
234	        return ge::GRAPH_FAILED);
235	
236	    return ge::GRAPH_SUCCESS;
237	}
238	
239	// --------------------------CheckBiasValid-------------------------------------
240	ge::graphStatus AiInfraMhcPreSplitPostResInfoParser::CheckBiasValid()
241	{
242	    const gert::StorageShape *biasShapePtr = context_->GetInputShape(MHC_BIAS_INDEX);
243	    OP_CHECK_IF(biasShapePtr == nullptr,
244	        OP_LOGE(context_->GetNodeName(), "bias InputShape is nullptr."),
245	        return ge::GRAPH_FAILED);
246	    OP_CHECK_IF(biasShapePtr->GetStorageShape().GetDimNum() != MHC_NUM_ONE,
247	        OP_LOGE(context_->GetNodeName(), "bias: number of dimensions must be 1."),
248	        return ge::GRAPH_FAILED);
249	    OP_CHECK_IF(biasShapePtr->GetStorageShape().GetDim(MHC_DIM_ZERO) != phiRows_,
250	        OP_LOGE(context_->GetNodeName(),
251	            "bias shape must be [%ld], got [%ld].",
252	            phiRows_,
253	            biasShapePtr->GetStorageShape().GetDim(MHC_DIM_ZERO)),
254	        return ge::GRAPH_FAILED);
255	
256	    auto biasDesc = context_->GetInputDesc(MHC_BIAS_INDEX);
257	    OP_CHECK_IF(biasDesc == nullptr, OP_LOGE(context_->GetNodeName(), "biasDesc is nullptr."), return ge::GRAPH_FAILED);
258	    OP_CHECK_IF(biasDesc->GetDataType() != ge::DataType::DT_FLOAT,
259	        OP_LOGE(context_->GetNodeName(), "bias dtype must be float32."),
260	        return ge::GRAPH_FAILED);
261	
262	    return ge::GRAPH_SUCCESS;
263	}
264	
265	// --------------------------GenerateTiling-------------------------------------
266	ge::graphStatus AiInfraMhcPreSplitPostResInfoParser::GenerateTiling()
267	{
268	    // D轴分块：设计文档规定 dimTile = min(D, 2560)，对齐128元素
269	    dimTile_ = D_ > MHC_DIM_TILE_MAX ? MHC_DIM_TILE_MAX : D_;
270	
271	    dimTile_ = (dimTile_ / MHC_ALIGN_ELEM) * MHC_ALIGN_ELEM;
272	    if (dimTile_ == MHC_NUM_ZERO) {
273	        dimTile_ = MHC_ALIGN_ELEM;
274	    }
275	
276	    // D轴需要几个tile
277	    dimLoop_ = (D_ + dimTile_ - MHC_NUM_ONE) / dimTile_;
278	
279	    // 每token使用核数：仅当 D<=2560（dimLoop==1）且 token 数不足以填满一半核数时启用双核
280	    // token 充足（totalLength >= coreNum/2）时单核已能饱和所有核，双核只引入额外开销
281	    bool needDualCore = (dimLoop_ == MHC_NUM_ONE) && (totalLength_ < static_cast<int64_t>(coreNum_) / MHC_NUM_TWO);
282	    coresPerToken_ = needDualCore ? MHC_NUM_TWO : MHC_NUM_ONE;
283	
284	    // phi行分配：双核模式下，phiRowMid是前半部分的行数
285	    // 前半行[0, phiRowMid) 对应 h_post(N行) + comb前半(N*N/2行)
286	    // 实际上双核按 phiRows/2 对半分
287	    phiRowMid_ = (coresPerToken_ == MHC_NUM_TWO) ? (phiRows_ / MHC_NUM_TWO) : phiRows_;
288	
289	    // tilingKey
290	    tilingKey_ = (dimLoop_ == MHC_NUM_ONE) ? MHC_PRE_SPLIT_TILING_KEY_SINGLE_TILE : MHC_PRE_SPLIT_TILING_KEY_MULTI_TILE;
291	
292	    // T轴按核组分配（一组 = coresPerToken 个核处理一个token范围）
293	    int64_t coreGroups = static_cast<int64_t>(coreNum_) / coresPerToken_;
294	    OP_CHECK_IF(coreGroups == MHC_NUM_ZERO,
295	        OP_LOGE(opName_, "coreGroups is 0, coreNum=%lu, coresPerToken=%ld.", coreNum_, coresPerToken_),
296	        return ge::GRAPH_FAILED);
297	
298	    baseT_ = (totalLength_ + coreGroups - MHC_NUM_ONE) / coreGroups;
299	    coreTAct_ = (totalLength_ + baseT_ - MHC_NUM_ONE) / baseT_;
300	    tailT_ = totalLength_ - (coreTAct_ - MHC_NUM_ONE) * baseT_;
301	
302	    // 实际启动核数
303	    blockDim_ = coreTAct_ * coresPerToken_;
304	
305	    const size_t wsBytes = 32;
306	    size_t *currentWorkspace = context_->GetWorkspaceSizes(1);
307	    OP_CHECK_IF(currentWorkspace == nullptr,
308	        OP_LOGE(opName_, "currentWorkspace is nullptr"),
309	        return ge::GRAPH_FAILED);
310	    currentWorkspace[0] = wsBytes;
311	
312	    // 保留，暂未使用
313	    // -------------------------------------------------------
314	    // ReduceSum work tensor 大小（float）：
315	    //   xTileElems = N * dimTile
316	    //   elementsPerRepeat = 256B / sizeof(float) = 64
317	    //   elementsPerBlock  =  32B / sizeof(float) = 8
318	    //   workNeed = RoundUp(xTileElems / 64, 8) * 8
319	    // -------------------------------------------------------
320	    int64_t xTileElems = N_ * dimTile_;
321	    int64_t workNeed = ((xTileElems / 64 + 7) / 8) * 8;
322	    if (workNeed < MIN_FP32_ALIGN_ELEM_SIZE)
323	        workNeed = MIN_FP32_ALIGN_ELEM_SIZE;  // 最小 FP32_ALIGN_ELEM = 8
324	    reduceWorkSize_ = workNeed;
325	
326	    // invK = 1/(N*D)，RmsNorm 均值系数；host 侧浮点运算，无 aicore 类型限制
327	    invK_ = 1.0f / static_cast<float>(N_ * D_);
328	
329	    OP_LOGD(context_->GetNodeName(), "wsBytes: %zu (blockDim=%ld, N=%ld, D=%ld)", wsBytes, blockDim_, N_, D_);
330	    OP_LOGD(context_->GetNodeName(), "reduceWorkSize: %ld (xTileElems=%ld)", reduceWorkSize_, xTileElems);
331	    OP_LOGD(context_->GetNodeName(), "invK: %f (N=%ld, D=%ld)", invK_, N_, D_);
332	
333	    return ge::GRAPH_SUCCESS;
334	}
335	
336	// --------------------------ParseAndCheck-------------------------------------
337	ge::graphStatus AiInfraMhcPreSplitPostResInfoParser::ParseAndCheck()
338	{
339	    if (ge::GRAPH_SUCCESS != GetOpName() || ge::GRAPH_SUCCESS != GetNpuInfo()) {
340	        return ge::GRAPH_FAILED;
341	    }
342	    if (ge::GRAPH_SUCCESS != GetAttrInfo()) {
343	        return ge::GRAPH_FAILED;
344	    }
345	    if (ge::GRAPH_SUCCESS != CheckXValid() || ge::GRAPH_SUCCESS != CheckPhiValid() ||
346	        ge::GRAPH_SUCCESS != CheckAlphaValid() || ge::GRAPH_SUCCESS != CheckBiasValid()) {
347	        return ge::GRAPH_FAILED;
348	    }
349	    if (ge::GRAPH_SUCCESS != GenerateTiling()) {
350	        return ge::GRAPH_FAILED;
351	    }
352	    return ge::GRAPH_SUCCESS;
353	}
354	
355	// --------------------------TilingPrepare函数定义-------------------------------------
356	static ge::graphStatus TilingPrepareForAiInfraMhcPreSplitPostRes(gert::TilingParseContext * /* context */)
357	{
358	    return ge::GRAPH_SUCCESS;
359	}
360	
361	// --------------------------DoTiling-------------------------------------
362	ge::graphStatus AiInfraMhcPreSplitPostResTiling::DoTiling()
363	{
364	    tilingData_.set_totalLength(totalLength_);
365	    tilingData_.set_N(N_);
366	    tilingData_.set_D(D_);
367	    tilingData_.set_phiRows(phiRows_);
368	    tilingData_.set_dimTile(dimTile_);
369	    tilingData_.set_dimLoop(dimLoop_);
370	    tilingData_.set_coresPerToken(coresPerToken_);
371	    tilingData_.set_phiRowMid(phiRowMid_);
372	    tilingData_.set_blockDim(blockDim_);
373	    tilingData_.set_baseT(baseT_);
374	    tilingData_.set_tailT(tailT_);
375	    tilingData_.set_coreTAct(coreTAct_);
376	    tilingData_.set_normEps(normEps_);
377	    tilingData_.set_reduceWorkSize(reduceWorkSize_);
378	    tilingData_.set_invK(invK_);
379	
380	    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
381	    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
382	    context_->SetTilingKey(tilingKey_);
383	    context_->SetBlockDim(blockDim_);
384	
385	    OP_LOGD(context_->GetNodeName(), "totalLength: %ld", totalLength_);
386	    OP_LOGD(context_->GetNodeName(), "N: %ld", N_);
387	    OP_LOGD(context_->GetNodeName(), "D: %ld", D_);
388	    OP_LOGD(context_->GetNodeName(), "phiRows: %ld", phiRows_);
389	    OP_LOGD(context_->GetNodeName(), "dimTile: %ld", dimTile_);
390	    OP_LOGD(context_->GetNodeName(), "dimLoop: %ld", dimLoop_);
391	    OP_LOGD(context_->GetNodeName(), "coresPerToken: %ld", coresPerToken_);
392	    OP_LOGD(context_->GetNodeName(), "phiRowMid: %ld", phiRowMid_);
393	    OP_LOGD(context_->GetNodeName(), "blockDim: %ld", blockDim_);
394	    OP_LOGD(context_->GetNodeName(), "baseT: %ld", baseT_);
395	    OP_LOGD(context_->GetNodeName(), "tailT: %ld", tailT_);
396	    OP_LOGD(context_->GetNodeName(), "coreTAct: %ld", coreTAct_);
397	    OP_LOGD(context_->GetNodeName(), "normEps: %f", normEps_);
398	    OP_LOGD(context_->GetNodeName(), "invK: %f", invK_);
399	    OP_LOGD(context_->GetNodeName(), "reduceWorkSize: %ld", reduceWorkSize_);
400	    OP_LOGD(context_->GetNodeName(), "tilingKey: %lu", tilingKey_);
401	    return ge::GRAPH_SUCCESS;
402	}
403	
404	// --------------------------Tiling函数定义---------------------------
405	static ge::graphStatus TilingForAiInfraMhcPreSplitPostRes(gert::TilingContext *context)
406	{
407	    OP_CHECK_IF(context == nullptr,
408	        OPS_REPORT_VECTOR_INNER_ERR("AiInfraMhcPreSplitPostRes", "Tiling context is null."),
409	        return ge::GRAPH_FAILED);
410	    AiInfraMhcPreSplitPostResTiling tiling(context);
411	    if (tiling.ParseAndCheck() != ge::GRAPH_SUCCESS) {
412	        return ge::GRAPH_FAILED;
413	    }
414	    return tiling.DoTiling();
415	}
416	
417	// --------------------------注册Tiling函数及TilingPrepare函数--------
418	IMPL_OP_OPTILING(AiInfraMhcPreSplitPostRes)
419	    .Tiling(TilingForAiInfraMhcPreSplitPostRes)
420	    .TilingParse<AiInfraMhcPreSplitPostResCompileInfo>(TilingPrepareForAiInfraMhcPreSplitPostRes);
421	
422	}  // namespace optiling
