11	/*!
12	 * \file ai_infra_mhc_pre_split_post_res_base.h
13	 * \brief KernelMhcBase<T>：SingleTile / MultiTile 共享的 GM 绑定、UB 分配和计算辅助函数
14	 */
15	
16	#ifndef AI_INFRA_MHC_PRE_SPLIT_POST_RES_BASE_H_
17	#define AI_INFRA_MHC_PRE_SPLIT_POST_RES_BASE_H_
18	
19	#include "kernel_operator.h"
20	#include "kernel_tiling/kernel_tiling.h"
21	
22	namespace AiInfraMhcPreSplitPostRes {
23	using namespace AscendC;
24	
25	constexpr int64_t FP32_BYTES = 4;           // float 单元素字节数
26	constexpr int64_t FP32_ALIGN_ELEM = 8;      // 向量操作最小对齐单位：32B / 4B = 8 个 float
27	constexpr int64_t DATACOPY_MIN_BYTES = 32;  // DataCopy 硬件要求最小块大小
28	
29	// 二叉树累加需要
30	// float 下每 repeat 最多处理 256B/4B = 64 个元素
31	constexpr uint32_t ONE_REP_FLOAT = 64u;
32	constexpr uint32_t DEFAULT_BLK_STRIDE = 1u;
33	constexpr uint32_t DEFAULT_REP_STRIDE = 8u;
34	constexpr uint32_t SIXTEEN_U = 16u;
35	constexpr uint32_t EIGHT_U = 8u;
36	
37	constexpr float FLOAT_ZERO = 0.0f;
38	constexpr float FLOAT_ONE = 1.0f;
39	constexpr float FLOAT_TWO = 2.0f;
40	
41	constexpr int32_t NUM_ZERO = 0;
42	constexpr int32_t NUM_ONE = 1;
43	constexpr int32_t NUM_TWO = 2;
44	
45	// 申请 event，SetFlag 后立即 WaitFlag，形成流水线屏障
46	template <HardEvent event>
47	__aicore__ inline void SetWaitFlag(TPipe *pipe)
48	{
49	    event_t eventId = static_cast<event_t>(pipe->FetchEventID(event));
50	    SetFlag<event>(eventId);
51	    WaitFlag<event>(eventId);
52	}
53	
54	template <typename T>
55	class KernelMhcBase {
56	protected:
57	    // 上取整到 FP32_ALIGN_ELEM 的整数倍（用于 UB float 数组对齐）
58	    __aicore__ inline int64_t AlignUp(int64_t n) const
59	    {
60	        return ((n + FP32_ALIGN_ELEM - 1) / FP32_ALIGN_ELEM) * FP32_ALIGN_ELEM;
61	    }
62	
63	    // 功能：将输入 tensor 进行二叉树折叠，直到元素数量 ≤ ONE_REP_FLOAT
64	    // 输出：折叠后的总元素数 totalNum
65	    __aicore__ inline uint32_t BinaryTreeFold(LocalTensor<float> &srcTmp, uint32_t totalNum)
66	    {
67	        while (totalNum > ONE_REP_FLOAT) {
68	            uint32_t halfNum = DivCeil(totalNum, SIXTEEN_U) * EIGHT_U;
69	            SetVectorMask<uint8_t, MaskMode::COUNTER>(0, totalNum - halfNum);
70	            BinaryRepeatParams bp;
71	            Add<float, false>(srcTmp, srcTmp, srcTmp[halfNum], MASK_PLACEHOLDER, 1, bp);
72	            PipeBarrier<PIPE_V>();
73	            totalNum = halfNum;
74	        }
75	        return totalNum;
76	    }
77	
78	    __aicore__ inline void InitGM(
79	        GM_ADDR xAddr, GM_ADDR phiAddr, GM_ADDR alphaAddr, GM_ADDR biasAddr, GM_ADDR hPostAddr, GM_ADDR hResAddr)
80	    {
81	        xGm_.SetGlobalBuffer((__gm__ T *)xAddr, static_cast<uint64_t>(totalLength_) * N_ * D_);
82	        phiGm_.SetGlobalBuffer((__gm__ float *)phiAddr, static_cast<uint64_t>(phiRows_) * N_ * D_);
83	        alphaGm_.SetGlobalBuffer((__gm__ float *)alphaAddr, NUM_TWO);  // [alpha0, alpha1]
84	        biasGm_.SetGlobalBuffer((__gm__ float *)biasAddr, static_cast<uint64_t>(phiRows_));
85	        hPostGm_.SetGlobalBuffer((__gm__ float *)hPostAddr, static_cast<uint64_t>(totalLength_) * N_);
86	        hResGm_.SetGlobalBuffer((__gm__ float *)hResAddr, static_cast<uint64_t>(totalLength_) * N_ * N_);
87	        alpha0_ = alphaGm_.GetValue(0);
88	        alpha1_ = alphaGm_.GetValue(1);
89	    }
90	
91	    // doubleBufferX=false（默认，SINGLE_TILE）：xInQueue_ depth=1，squareBuf_ 正常初始化。
92	    // doubleBufferX=true（MULTI_TILE）：xInQueue_ depth=2，MTE2 CopyIn 与 Cast/AccumSumSq 重叠；
93	    //   squareBuf_ 跳过 InitBuffer（不占 UB），AccumSumSq 改为原地 Mul 到 xFp32，净省 UB。
94	    __aicore__ inline void InitCommonBuffers(
95	        TPipe *pipe, int64_t dimTile, int64_t reduceWorkSize, bool doubleBufferX = false)
96	    {
97	        int64_t xTileElems = N_ * dimTile;
98	        // xInQueue_ depth：SINGLE_TILE=1，MULTI_TILE=2（双缓冲）
99	        pipe->InitBuffer(xInQueue_, doubleBufferX ? 2 : 1, static_cast<uint32_t>(xTileElems * sizeof(T)));
100	        pipe->InitBuffer(xFp32Buf_, static_cast<uint32_t>(xTileElems * FP32_BYTES));
101	        // phiRowQue_ 深度 2：一个 tile 在 MTE2 传输，同时另一个 tile 在向量计算
102	        pipe->InitBuffer(phiRowQue_, NUM_TWO, static_cast<uint32_t>(xTileElems * FP32_BYTES));
103	
104	        // xHatBuf_ / biasBuf_：AlignUp(phiRows_) + FP32_ALIGN_ELEM 额外 padding, （防卫padding）
105	        int64_t xHatAligned = AlignUp(phiRows_) + FP32_ALIGN_ELEM;
106	        pipe->InitBuffer(xHatBuf_, static_cast<uint32_t>(xHatAligned * FP32_BYTES));
107	        pipe->InitBuffer(biasBuf_, static_cast<uint32_t>(xHatAligned * FP32_BYTES));
108	
109	        // sumSqBuf_：存放 ReduceSum(x^2) 的累加结果，大小 FP32_ALIGN_ELEM 个 float
110	        // squareBuf_：存放 x^2 的中间结果（MULTI_TILE 跳过，改用原地 Mul 节省 UB）
111	        // sumSqDotBuf_ / dotBuf_：布局为 [result(FP32_ALIGN_ELEM float) | work(reduceWorkSize float)]
112	        // reduceBufElems : ReduceSum api所需空间，ADD+WholeReduceSum实现后未使用，暂时保存。
113	        int64_t reduceBufElems = FP32_ALIGN_ELEM + reduceWorkSize;
114	        pipe->InitBuffer(sumSqBuf_, static_cast<uint32_t>(FP32_ALIGN_ELEM * FP32_BYTES));
115	        if (!doubleBufferX) {
116	            // SINGLE_TILE：AccumSumSq 需要 squareBuf_ 暂存 x^2（xFp32 在后续 ComputePhiDot 中仍需使用）
117	            pipe->InitBuffer(squareBuf_, static_cast<uint32_t>(xTileElems * FP32_BYTES));
118	        }
119	        pipe->InitBuffer(dotBuf_, static_cast<uint32_t>(reduceBufElems * FP32_BYTES));
120	        pipe->InitBuffer(sumSqDotBuf_, static_cast<uint32_t>(reduceBufElems * FP32_BYTES));
121	
122	        pipe->InitBuffer(hPostOutQueue_, 1, static_cast<uint32_t>(AlignUp(N_) * FP32_BYTES));
123	        pipe->InitBuffer(hResOutQueue_, 1, static_cast<uint32_t>(AlignUp(N_ * N_) * FP32_BYTES));
124	    }
125	
126	    // 从 xGm_[xTokenOff + dimOff] 搬入当前 token 的一个 dimTile（N 行 × copyD 列）到 xInQueue_
127	    __aicore__ inline void CopyInXTile(int64_t xTokenOff, int64_t dimOff, int64_t copyD)
128	    {
129	        LocalTensor<T> xLocal = xInQueue_.AllocTensor<T>();
130	        DataCopyExtParams cp;
131	        cp.blockCount = static_cast<uint16_t>(N_);
132	        cp.blockLen = static_cast<uint32_t>(copyD * sizeof(T));
133	        cp.srcStride = static_cast<uint32_t>((D_ - copyD) * sizeof(T));
134	        cp.dstStride = 0;
135	        DataCopyPadExtParams<T> pad{false, 0, 0, 0};
136	        DataCopyPad(xLocal, xGm_[xTokenOff + dimOff], cp, pad);
137	        xInQueue_.EnQue(xLocal);
138	    }
139	
140	    // 计算 xFp32 的元素平方和并累加到 sumSq[0]（处理当前 dimTile，N×copyD 个元素）
141	    //
142	    // inPlace=false（默认，SINGLE_TILE）：将 x^2 写入 squareBuf_，xFp32 内容保持不变，
143	    //   供后续 ComputePhiDot 复用。
144	    // inPlace=true（MULTI_TILE Phase A）：将 x^2 原地写回 xFp32（squareBuf_ 未初始化，不可用）。
145	    //   调用方在此之后立即 FreeTensor(xLocal) 并不再读 xFp32，原地覆盖安全。
146	    template <bool INPLACE>
147	    __aicore__ inline void AccumSumSq(LocalTensor<float> &xFp32, LocalTensor<float> &sumSq, int64_t copyD, TPipe *pipe)
148	    {
149	        LocalTensor<float> sqDot = sumSqDotBuf_.Get<float>();
150	        uint32_t totalNum = static_cast<uint32_t>(N_ * copyD);
151	        LocalTensor<float> srcTmp;
152	        if constexpr (!INPLACE) {
153	            // SINGLE_TILE：用 squareBuf_ 暂存 x^2，保留 xFp32 原始值
154	            LocalTensor<float> square = squareBuf_.Get<float>();
155	            Mul(square, xFp32, xFp32, static_cast<uint32_t>(N_ * copyD));
156	            PipeBarrier<PIPE_V>();
157	            // 二叉树折叠 + WholeReduceSum，与 ComputePhiDot 保持一致
158	            SetMaskCount();
159	            srcTmp = square;
160	            // 调用通用二叉树折叠
161	            totalNum = BinaryTreeFold(srcTmp, totalNum);
162	        } else {
163	            // MULTI_TILE Phase A：原地 Mul，xFp32 被覆盖为 x^2；squareBuf_ 不访问
164	            Mul(xFp32, xFp32, xFp32, static_cast<uint32_t>(N_ * copyD));
165	            PipeBarrier<PIPE_V>();
166	            // 二叉树折叠 + WholeReduceSum，与 ComputePhiDot 保持一致
167	            SetMaskCount();
168	            srcTmp = xFp32;
169	            // 调用通用二叉树折叠
170	            totalNum = BinaryTreeFold(srcTmp, totalNum);
171	        }
172	        SetVectorMask<uint8_t, MaskMode::COUNTER>(0, totalNum);
173	        WholeReduceSum<float, false>(
174	            sqDot, srcTmp, MASK_PLACEHOLDER, 1, DEFAULT_BLK_STRIDE, DEFAULT_BLK_STRIDE, DEFAULT_REP_STRIDE);
175	        SetWaitFlag<HardEvent::V_S>(pipe);
176	        ResetMask();
177	        SetMaskNorm();
178	        // GetValue/SetValue 是标量读写，不发 V 指令，无需 PipeBarrier
179	        sumSq.SetValue(0, sumSq.GetValue(0) + sqDot.GetValue(0));
180	    }
181	
182	    // 发起 phi[row] 第 dimOff 列起 copyD 列的 MTE2 搬入，结果入队 phiRowQue_（不等待）
183	    __aicore__ inline void PrefetchPhiRow(int64_t row, int64_t dimOff, int64_t copyD)
184	    {
185	        LocalTensor<float> phiRow = phiRowQue_.AllocTensor<float>();
186	        DataCopyExtParams cp;
187	        cp.blockCount = static_cast<uint16_t>(N_);
188	        cp.blockLen = static_cast<uint32_t>(copyD * FP32_BYTES);
189	        cp.srcStride = static_cast<uint32_t>((D_ - copyD) * FP32_BYTES);
190	        cp.dstStride = 0;
191	        DataCopyPadExtParams<float> pad{false, 0, 0, 0};
192	        DataCopyPad(phiRow, phiGm_[row * N_ * D_ + dimOff], cp, pad);
193	        phiRowQue_.EnQue(phiRow);
194	    }
195	
196	    // 从 phiRowQue_ 取出 phi 行，与 xFp32 逐元素乘后 ReduceSum，结果累加到 xHat[localIdx]
197	    // 使用二叉树折叠（BinaryReduceSum）：先 Add 对半折叠至 ≤ONE_REP_FLOAT 个元素，
198	    // 再 WholeReduceSum 收尾，全程二叉树累加，规避顺序累加的精度误差。
199	    __aicore__ inline void ComputePhiDot(
200	        LocalTensor<float> &xFp32, LocalTensor<float> &xHat, int64_t localIdx, int64_t copyD, TPipe *pipe)
201	    {
202	        LocalTensor<float> phiRow = phiRowQue_.DeQue<float>();
203	        LocalTensor<float> dot = dotBuf_.Get<float>();
204	
205	        Mul(phiRow, phiRow, xFp32, static_cast<uint32_t>(N_ * copyD));
206	        PipeBarrier<PIPE_V>();
207	
208	        // 二叉树折叠：每轮将后半段加到前半段，直至剩余 ≤ ONE_REP_FLOAT 个元素
209	        // phiRow 空间 = N_*D floats（由 phiRowQue_ 保证），原地操作安全
210	        SetMaskCount();
211	        uint32_t totalNum = static_cast<uint32_t>(N_ * copyD);
212	        LocalTensor<float> srcTmp = phiRow;
213	        // 调用通用二叉树折叠
214	        totalNum = BinaryTreeFold(srcTmp, totalNum);
215	
216	        // 最后一轮：≤ 64 个元素，WholeReduceSum 一次收尾（全二叉树）
217	        SetVectorMask<uint8_t, MaskMode::COUNTER>(0, totalNum);
218	        WholeReduceSum<float, false>(
219	            dot, srcTmp, MASK_PLACEHOLDER, 1, DEFAULT_BLK_STRIDE, DEFAULT_BLK_STRIDE, DEFAULT_REP_STRIDE);
220	        SetWaitFlag<HardEvent::V_S>(pipe);
221	        ResetMask();
222	        SetMaskNorm();
223	
224	        // GetValue/SetValue 是标量读写，不发 V 指令；无需 PipeBarrier
225	        xHat.SetValue(localIdx, xHat.GetValue(localIdx) + dot.GetValue(0));
226	        phiRowQue_.FreeTensor(phiRow);
227	    }
228	
229	    // 搬入 count bias 到 biasLocal，
230	    __aicore__ inline void CopyInBias(LocalTensor<float> biasLocal, int64_t biasStart, int64_t count, TPipe *pipe)
231	    {
232	        int64_t available = phiRows_ - biasStart;
233	        DataCopyExtParams params;
234	        params.blockCount = 1;
235	        params.srcStride = 0;
236	        params.dstStride = 0;
237	        params.blockLen = static_cast<uint32_t>(count * FP32_BYTES);
238	        DataCopyPadExtParams<float> pad{false, 0, 0, 0.0f};
239	        DataCopyPad(biasLocal, biasGm_[biasStart], params, pad);
240	
241	        SetWaitFlag<HardEvent::MTE2_V>(pipe);
242	    }
243	
244	    // 计算 hPostOut = 2*sigmoid(alpha0*xHat[0:postCount] + biasLocal[0:postCount])，
245	    // 写出到 hPostGm_[tokenIdx*N + gmRowStart : gmRowStart+postCount)
246	    __aicore__ inline void ComputeAndWriteHPost(int64_t tokenIdx, LocalTensor<float> &xHat,
247	        LocalTensor<float> &biasLocal, int64_t gmRowStart, int64_t postCount, TPipe *pipe)
248	    {
249	        LocalTensor<float> hPostOut = hPostOutQueue_.AllocTensor<float>();
250	        Muls(hPostOut, xHat, alpha0_, static_cast<uint32_t>(postCount));
251	        PipeBarrier<PIPE_V>();
252	        Add(hPostOut, hPostOut, biasLocal, static_cast<uint32_t>(postCount));
253	        PipeBarrier<PIPE_V>();
254	        Sigmoid<float, true>(hPostOut, hPostOut, static_cast<uint32_t>(postCount));
255	        PipeBarrier<PIPE_V>();
256	        Muls(hPostOut, hPostOut, FLOAT_TWO, static_cast<uint32_t>(postCount));
257	        SetWaitFlag<HardEvent::V_MTE3>(pipe);
258	        DataCopyExtParams op;
259	        op.blockCount = 1;
260	        op.blockLen = static_cast<uint32_t>(postCount * FP32_BYTES);
261	        op.srcStride = 0;
262	        op.dstStride = 0;
263	        DataCopyPad(hPostGm_[tokenIdx * N_ + gmRowStart], hPostOut, op);
264	        hPostOutQueue_.FreeTensor(hPostOut);
265	    }
266	
267	    // 计算 hResOut = alpha1*xHat[localOff:localOff+resCount] + biasLocal[localOff:localOff+resCount]，
268	    // 写出到 hResGm_[tokenIdx*N*N + (gmRowStart-N) : (gmRowStart-N)+resCount)
269	    __aicore__ inline void ComputeAndWriteHRes(int64_t tokenIdx, LocalTensor<float> &xHat,
270	        LocalTensor<float> &biasLocal, int64_t gmRowStart, int64_t localOff, int64_t resCount, TPipe *pipe)
271	    {
272	        LocalTensor<float> hResOut = hResOutQueue_.AllocTensor<float>();
273	        Muls(hResOut, xHat[localOff], alpha1_, static_cast<uint32_t>(resCount));
274	        PipeBarrier<PIPE_V>();
275	        Add(hResOut, hResOut, biasLocal[localOff], static_cast<uint32_t>(resCount));
276	        PipeBarrier<PIPE_V>();
277	        SetWaitFlag<HardEvent::V_MTE3>(pipe);
278	        DataCopyExtParams op;
279	        op.blockCount = 1;
280	        op.blockLen = static_cast<uint32_t>(resCount * FP32_BYTES);
281	        op.srcStride = 0;
282	        op.dstStride = 0;
283	        DataCopyPad(hResGm_[tokenIdx * N_ * N_ + (gmRowStart - N_)], hResOut, op);
284	        hResOutQueue_.FreeTensor(hResOut);
285	    }
286	
287	protected:
288	    GlobalTensor<T> xGm_;
289	    GlobalTensor<float> phiGm_;
290	    GlobalTensor<float> alphaGm_;
291	    GlobalTensor<float> biasGm_;
292	    GlobalTensor<float> hPostGm_;
293	    GlobalTensor<float> hResGm_;
294	
295	    // depth=2：SINGLE_TILE 路径 InitBuffer 传 depth=1（仅用1个slot），
296	    // MULTI_TILE 路径传 depth=2，启用 MTE2/Vector 双缓冲流水。
297	    TQue<TPosition::VECIN, NUM_TWO> xInQueue_;
298	    TQue<TPosition::VECOUT, NUM_ONE> hPostOutQueue_;
299	    TQue<TPosition::VECOUT, NUM_ONE> hResOutQueue_;
300	    TBuf<TPosition::VECCALC> xFp32Buf_;
301	    TQue<TPosition::VECIN, NUM_TWO> phiRowQue_;
302	    TBuf<TPosition::VECCALC> xHatBuf_;
303	    TBuf<TPosition::VECCALC> sumSqBuf_;
304	    TBuf<TPosition::VECCALC> squareBuf_;
305	    TBuf<TPosition::VECCALC> dotBuf_;
306	    TBuf<TPosition::VECCALC> sumSqDotBuf_;
307	    TBuf<TPosition::VECCALC> biasBuf_;
308	
309	    int64_t totalLength_ = 0;
310	    int64_t N_ = 0;
311	    int64_t D_ = 0;
312	    int64_t phiRows_ = 0;
313	    float normEps_ = 1e-6f;
314	    float alpha0_ = 1.0f;
315	    float alpha1_ = 1.0f;
316	    float invK_ = 0.0f;  // 1/(N*D)，由 tiling 传入
317	};
318	
319	}  // namespace AiInfraMhcPreSplitPostRes
320	
321	#endif  // AI_INFRA_MHC_PRE_SPLIT_POST_RES_BASE_H_

