11	/*!
12	 * \file ai_infra_mhc_pre_split_post_res_single_tile.h
13	 * \brief KernelMhcSingleTile<T>：SINGLE_TILE 路径（dimLoop==1，全量 D 一次搬入）
14	 *
15	 * 每个 token 由 coresPerToken（==2）个核并行处理，phi 行按 phiRowMid 对半分：
16	 *   core0 (phiRowStart=0)        ：处理 h_post 行 [0, N) 和 h_res 行 [N, phiRowMid)
17	 *   core1 (phiRowStart=phiRowMid)：处理 h_res 行 [phiRowMid, phiRows)
18	 *
19	 * xHat 本地下标规则（phiRowStart 由调用方传入）：
20	 *   row < N_  → row - phiRowStart          （core0 的 h_post 段，phiRowStart==0）
21	 *   row >= N_ → AlignUp(postCount) + (row - resStart)  （h_res 段）
22	 */
23	
24	#ifndef AI_INFRA_MHC_PRE_SPLIT_POST_RES_SINGLE_TILE_H_
25	#define AI_INFRA_MHC_PRE_SPLIT_POST_RES_SINGLE_TILE_H_
26	
27	#include "ai_infra_mhc_pre_split_post_res_base.h"
28	
29	namespace AiInfraMhcPreSplitPostRes {
30	using namespace AscendC;
31	
32	template <typename T>
33	class KernelMhcSingleTile : public KernelMhcBase<T> {
34	    using Base = KernelMhcBase<T>;
35	    using Base::AccumSumSq;
36	    using Base::AlignUp;
37	    using Base::alpha0_;
38	    using Base::alpha1_;
39	    using Base::biasBuf_;
40	    using Base::ComputeAndWriteHPost;
41	    using Base::ComputeAndWriteHRes;
42	    using Base::ComputePhiDot;
43	    using Base::CopyInBias;
44	    using Base::CopyInXTile;
45	    using Base::D_;
46	    using Base::InitCommonBuffers;
47	    using Base::InitGM;
48	    using Base::invK_;
49	    using Base::N_;
50	    using Base::normEps_;
51	    using Base::phiRows_;
52	    using Base::PrefetchPhiRow;
53	    using Base::sumSqBuf_;
54	    using Base::totalLength_;
55	    using Base::xFp32Buf_;
56	    using Base::xGm_;
57	    using Base::xHatBuf_;
58	    using Base::xInQueue_;
59	
60	public:
61	    __aicore__ inline KernelMhcSingleTile()
62	    {}
63	
64	    __aicore__ inline void Init(GM_ADDR xAddr, GM_ADDR phiAddr, GM_ADDR alphaAddr, GM_ADDR biasAddr, GM_ADDR hPostAddr,
65	        GM_ADDR hResAddr, GM_ADDR workspace, TPipe *pipe, const AiInfraMhcPreSplitPostResTilingData *tiling)
66	    {
67	        pipe_ = pipe;
68	        totalLength_ = tiling->totalLength;
69	        N_ = tiling->N;
70	        D_ = tiling->D;
71	        phiRows_ = tiling->phiRows;
72	        normEps_ = tiling->normEps;
73	        invK_ = tiling->invK;
74	        phiRowMid_ = tiling->phiRowMid;
75	        blockDim_ = tiling->blockDim;
76	        baseT_ = tiling->baseT;
77	        tailT_ = tiling->tailT;
78	        coreTAct_ = tiling->coreTAct;
79	        coresPerToken_ = tiling->coresPerToken;
80	
81	        InitGM(xAddr, phiAddr, alphaAddr, biasAddr, hPostAddr, hResAddr);
82	        // dimTile 传入 D_，表示全量 D 一次搬入，无 dimLoop 循环
83	        InitCommonBuffers(pipe, D_, tiling->reduceWorkSize);
84	    }
85	
86	    __aicore__ inline void Process()
87	    {
88	        int64_t blockIdx = GetBlockIdx();
89	        int64_t groupIdx = blockIdx / coresPerToken_;  // token 组索引
90	        int64_t localIdx = blockIdx % coresPerToken_;  // 组内核索引（0 或 1）
91	
92	        if (groupIdx >= coreTAct_) {
93	            return;
94	        }
95	
96	        int64_t tStart = groupIdx * baseT_;
97	        int64_t tCount = (groupIdx == coreTAct_ - NUM_ONE) ? tailT_ : baseT_;
98	
99	        // localIdx==NUM_ZERO: 处理 phi 行 [NUM_ZERO, phiRowMid)；localIdx==NUM_ONE: 处理 [phiRowMid, phiRows)
100	        int64_t phiRowStart = (localIdx == NUM_ONE) ? phiRowMid_ : NUM_ZERO;
101	        int64_t phiRowEnd = (localIdx == NUM_ZERO) ? phiRowMid_ : phiRows_;
102	
103	        for (int64_t t = 0; t < tCount; t++) {
104	            ProcessOneToken(tStart + t, phiRowStart, phiRowEnd);
105	        }
106	    }
107	
108	private:
109	    // 将 phi 行号映射到 xHat 本地下标：
110	    //   row < N_  → row - phiRowStart（core0 h_post 段，phiRowStart==0）
111	    //   row >= N_ → AlignUp(postCount) + (row - resStart)（h_res 段）
112	    __aicore__ inline int64_t LocalIdxOf(int64_t row, int64_t phiRowStart) const
113	    {
114	        if (row < N_) {
115	            return row - phiRowStart;
116	        }
117	        int64_t postCount = (N_ > phiRowStart) ? (N_ - phiRowStart) : NUM_ZERO;
118	        int64_t resStart = (phiRowStart >= N_) ? phiRowStart : N_;
119	        return AlignUp(postCount) + (row - resStart);
120	    }
121	
122	    __aicore__ inline void ProcessOneToken(int64_t tokenIdx, int64_t phiRowStart, int64_t phiRowEnd)
123	    {
124	        int64_t xTokenOff = tokenIdx * N_ * D_;
125	
126	        int64_t copyD = D_;
127	
128	        CopyInXTile(xTokenOff, 0, copyD);
129	        LocalTensor<T> xLocal = this->xInQueue_.template DeQue<T>();
130	        LocalTensor<float> xFp32 = this->xFp32Buf_.template Get<float>();
131	        Cast(xFp32, xLocal, RoundMode::CAST_NONE, static_cast<uint32_t>(N_ * copyD));
132	        PipeBarrier<PIPE_V>();
133	        this->xInQueue_.FreeTensor(xLocal);
134	
135	        // 计算全量 x 的平方和，invRms = 1/sqrt(mean(x^2) + eps)
136	        LocalTensor<float> sumSq = this->sumSqBuf_.template Get<float>();
137	        Duplicate(sumSq, FLOAT_ZERO, static_cast<uint32_t>(FP32_ALIGN_ELEM));
138	        PipeBarrier<PIPE_V>();
139	        this->template AccumSumSq<false>(xFp32, sumSq, copyD, pipe_);
140	        float invRms = FLOAT_ONE / sqrt(sumSq.GetValue(NUM_ZERO) * invK_ + normEps_);
141	
142	        // 对本核负责的 phi 行做双缓冲流水：预取 row+1 与计算 row 重叠
143	        LocalTensor<float> xHat = this->xHatBuf_.template Get<float>();
144	        Duplicate(xHat, FLOAT_ZERO, static_cast<uint32_t>(AlignUp(phiRows_)));
145	        PipeBarrier<PIPE_V>();
146	
147	        PrefetchPhiRow(phiRowStart, 0, copyD);
148	        for (int64_t row = phiRowStart; row < phiRowEnd - 1; row++) {
149	            PrefetchPhiRow(row + 1, 0, copyD);
150	            ComputePhiDot(xFp32, xHat, LocalIdxOf(row, phiRowStart), copyD, pipe_);
151	        }
152	        ComputePhiDot(xFp32, xHat, LocalIdxOf(phiRowEnd - 1, phiRowStart), copyD, pipe_);
153	
154	        // xHat 乘以 invRms，完成 RMS norm
155	        int64_t rowCount = phiRowEnd - phiRowStart;
156	        int64_t xHatUsed = (phiRowEnd <= N_) ? rowCount : LocalIdxOf(phiRowEnd - 1, phiRowStart) + 1;
157	        Muls(xHat, xHat, invRms, static_cast<uint32_t>(xHatUsed));
158	        PipeBarrier<PIPE_V>();
159	
160	        LocalTensor<float> biasLocal = this->biasBuf_.template Get<float>();
161	
162	        // 本核有 h_post 段（仅 core0，phiRowStart < N_）
163	        if (phiRowStart < N_) {
164	            int64_t postCount = N_ - phiRowStart;
165	            CopyInBias(biasLocal, phiRowStart, postCount, pipe_);
166	            ComputeAndWriteHPost(tokenIdx, xHat, biasLocal, phiRowStart, postCount, pipe_);
167	        }
168	
169	        // 本核有 h_res 段（core0: [N_, phiRowMid)；core1: [phiRowMid, phiRows)）
170	        int64_t resStart = (phiRowStart >= N_) ? phiRowStart : N_;
171	        if (resStart < phiRowEnd) {
172	            int64_t resCount = phiRowEnd - resStart;
173	            int64_t resLocalOff = LocalIdxOf(resStart, phiRowStart);
174	            CopyInBias(biasLocal[resLocalOff], resStart, resCount, pipe_);
175	            ComputeAndWriteHRes(tokenIdx, xHat, biasLocal, resStart, resLocalOff, resCount, pipe_);
176	        }
177	    }
178	
179	private:
180	    TPipe *pipe_ = nullptr;
181	    int64_t phiRowMid_ = 0;
182	    int64_t blockDim_ = 0;
183	    int64_t baseT_ = 0;
184	    int64_t tailT_ = 0;
185	    int64_t coreTAct_ = 0;
186	    int64_t coresPerToken_ = 0;
187	};
188	
189	}  // namespace AiInfraMhcPreSplitPostRes
190	
191	#endif  // AI_INFRA_MHC_PRE_SPLIT_POST_RES_SINGLE_TILE_H_
