11	/*!
12	 * \file ai_infra_mhc_pre_split_post_res_multi_tile.h
13	 * \brief KernelMhcMultiTile<T>：MULTI_TILE 路径（dimLoop>1，D 分多个 dimTile 处理）
14	 *
15	 * 每个 token 由单核处理（coresPerToken==1），处理全部 phiRows 行。
16	 * 每个 token 分两轮遍历 dimTile：
17	 *   Phase A：逐 tile CopyIn x 并 Cast，累加平方和，循环结束后计算 invRms
18	 *   Phase B：再次逐 tile CopyIn x 并 Cast，对所有 phi 行做双缓冲流水 dot 计算
19	 *            （Phase A 的 xFp32 未持久化，Phase B 需从 xGm_ 重读）
20	 *
21	 * xHat 本地下标规则：
22	 *   row < N_  → row
23	 *   row >= N_ → AlignUp(N_) + (row - N_)
24	 */
25	
26	#ifndef AI_INFRA_MHC_PRE_SPLIT_POST_RES_KERNEL_MULTI_TILE_H_
27	#define AI_INFRA_MHC_PRE_SPLIT_POST_RES_KERNEL_MULTI_TILE_H_
28	
29	#include "ai_infra_mhc_pre_split_post_res_single_tile.h"
30	
31	namespace AiInfraMhcPreSplitPostRes {
32	using namespace AscendC;
33	
34	template <typename T>
35	class KernelMhcMultiTile : public KernelMhcBase<T> {
36	    using Base = KernelMhcBase<T>;
37	    using Base::AccumSumSq;
38	    using Base::AlignUp;
39	    using Base::alpha0_;
40	    using Base::alpha1_;
41	    using Base::biasBuf_;
42	    using Base::ComputeAndWriteHPost;
43	    using Base::ComputeAndWriteHRes;
44	    using Base::ComputePhiDot;
45	    using Base::CopyInBias;
46	    using Base::CopyInXTile;
47	    using Base::D_;
48	    using Base::InitCommonBuffers;
49	    using Base::InitGM;
50	    using Base::invK_;
51	    using Base::N_;
52	    using Base::normEps_;
53	    using Base::phiRows_;
54	    using Base::PrefetchPhiRow;
55	    using Base::sumSqBuf_;
56	    using Base::totalLength_;
57	    using Base::xFp32Buf_;
58	    using Base::xGm_;
59	    using Base::xHatBuf_;
60	    using Base::xInQueue_;
61	
62	public:
63	    __aicore__ inline KernelMhcMultiTile()
64	    {}
65	
66	    __aicore__ inline void Init(GM_ADDR xAddr, GM_ADDR phiAddr, GM_ADDR alphaAddr, GM_ADDR biasAddr, GM_ADDR hPostAddr,
67	        GM_ADDR hResAddr, GM_ADDR workspaceAddr, TPipe *pipe, const AiInfraMhcPreSplitPostResTilingData *tiling)
68	    {
69	        pipe_ = pipe;
70	        totalLength_ = tiling->totalLength;
71	        N_ = tiling->N;
72	        D_ = tiling->D;
73	        phiRows_ = tiling->phiRows;
74	        dimTile_ = tiling->dimTile;
75	        dimLoop_ = tiling->dimLoop;
76	        normEps_ = tiling->normEps;
77	        invK_ = tiling->invK;
78	        baseT_ = tiling->baseT;
79	        tailT_ = tiling->tailT;
80	        coreTAct_ = tiling->coreTAct;
81	
82	        InitGM(xAddr, phiAddr, alphaAddr, biasAddr, hPostAddr, hResAddr);
83	        // doubleBufferX=true：xInQueue_ depth=2，MTE2 CopyIn(tile d+1) 与
84	        // Cast+AccumSumSq(tile d) 重叠；squareBuf_ 跳过 InitBuffer（原地 Mul 替代）
85	        InitCommonBuffers(pipe, dimTile_, tiling->reduceWorkSize, true);
86	    }
87	
88	    __aicore__ inline void Process()
89	    {
90	        int64_t groupIdx = GetBlockIdx();  // coresPerToken==1，blockIdx 即 token 组索引
91	        if (groupIdx >= coreTAct_) {
92	            return;
93	        }
94	
95	        int64_t tStart = groupIdx * baseT_;
96	        int64_t tCount = (groupIdx == coreTAct_ - 1) ? tailT_ : baseT_;
97	
98	        for (int64_t t = 0; t < tCount; t++) {
99	            ProcessOneToken(tStart + t);
100	        }
101	    }
102	
103	private:
104	    // 将 phi 行号映射到 xHat 本地下标：
105	    //   row < N_  → row
106	    //   row >= N_ → AlignUp(N_) + (row - N_)
107	    __aicore__ inline int64_t LocalIdxOf(int64_t row) const
108	    {
109	        if (row < N_)
110	            return row;
111	        return AlignUp(N_) + (row - N_);
112	    }
113	
114	    // 计算 tile d 的 copyD：最后一个 tile 取尾部实际列数，其余取 dimTile_
115	    __aicore__ inline int64_t TileCopyD(int64_t d) const
116	    {
117	        int64_t dimOff = d * dimTile_;
118	        int64_t copyDRaw = (d == dimLoop_ - 1) ? (D_ - dimOff) : dimTile_;
119	        return copyDRaw;
120	    }
121	
122	    __aicore__ inline void ProcessOneToken(int64_t tokenIdx)
123	    {
124	        int64_t xTokenOff = tokenIdx * N_ * D_;
125	
126	        // ── Phase A：双缓冲流水累加 sumSq ────────────────────────────
127	        //
128	        // 流水时序（depth=2 队列，MTE2 与 Vector 重叠）：
129	        //
130	        //   prefetch d=0                          （MTE2[0] 发出）
131	        //   loop d = 0 .. dimLoop_-2:
132	        //     prefetch d+1                        （MTE2[d+1] 发出，与下面的 V 重叠）
133	        //     dequeue d → Cast → AccumSumSq(d)    （V[d]，与 MTE2[d+1] 并行）
134	        //   dequeue dimLoop_-1 → Cast → AccumSumSq （收尾：无下一个 MTE2）
135	        //
136	        LocalTensor<float> sumSq = this->sumSqBuf_.template Get<float>();
137	        Duplicate(sumSq, FLOAT_ZERO, static_cast<uint32_t>(FP32_ALIGN_ELEM));
138	        PipeBarrier<PIPE_V>();
139	
140	        // 预取 tile 0
141	        CopyInXTile(xTokenOff, 0, TileCopyD(0));
142	
143	        for (int64_t d = 0; d < dimLoop_ - 1; d++) {
144	            int64_t copyD = TileCopyD(d);
145	            int64_t copyDNext = TileCopyD(d + 1);
146	
147	            // 先发下一个 tile 的 MTE2（与当前 tile 的向量计算重叠）
148	            CopyInXTile(xTokenOff, (d + 1) * dimTile_, copyDNext);
149	
150	            // 等待当前 tile 就绪，Cast → AccumSumSq（原地 Mul）
151	            LocalTensor<T> xLocal = this->xInQueue_.template DeQue<T>();
152	            LocalTensor<float> xFp32 = this->xFp32Buf_.template Get<float>();
153	            Cast(xFp32, xLocal, RoundMode::CAST_NONE, static_cast<uint32_t>(N_ * copyD));
154	            PipeBarrier<PIPE_V>();
155	            this->xInQueue_.FreeTensor(xLocal);
156	            // AccumSumSq 末尾已无 PipeBarrier，sumSq.SetValue 是标量写，
157	            // 下一次循环的 CopyInXTile 不依赖 V 流水，无需额外屏障
158	            this->template AccumSumSq<true>(xFp32, sumSq, copyD, pipe_);
159	        }
160	
161	        // 收尾：处理最后一个 tile（已由上一轮或首次预取发出）
162	        {
163	            int64_t copyD = TileCopyD(dimLoop_ - 1);
164	            LocalTensor<T> xLocal = this->xInQueue_.template DeQue<T>();
165	            LocalTensor<float> xFp32 = this->xFp32Buf_.template Get<float>();
166	            Cast(xFp32, xLocal, RoundMode::CAST_NONE, static_cast<uint32_t>(N_ * copyD));
167	            PipeBarrier<PIPE_V>();
168	            this->xInQueue_.FreeTensor(xLocal);
169	            // sumSq.GetValue(0) 是标量读，不依赖 V 流水，无需 PipeBarrier
170	            this->template AccumSumSq<true>(xFp32, sumSq, copyD, pipe_);
171	        }
172	
173	        float invRms = FLOAT_ONE / sqrt(sumSq.GetValue(NUM_ZERO) * invK_ + normEps_);
174	
175	        // ── Phase B：双缓冲流水计算 xHat ─────────────────────────────
176	        //
177	        // 流水时序同 Phase A：先 prefetch d+1，再处理 d。
178	        // 每个 tile 内部 phiRowQue_（depth=2）已对 phi 行做双缓冲，
179	        // 此处外层对 x tile 的 MTE2 再加一层重叠。
180	        //
181	        LocalTensor<float> xHat = this->xHatBuf_.template Get<float>();
182	        Duplicate(xHat, FLOAT_ZERO, static_cast<uint32_t>(AlignUp(phiRows_)));
183	        PipeBarrier<PIPE_V>();
184	
185	        // 预取 tile 0
186	        CopyInXTile(xTokenOff, 0, TileCopyD(0));
187	
188	        for (int64_t d = 0; d < dimLoop_ - 1; d++) {
189	            int64_t dimOff = d * dimTile_;
190	            int64_t copyD = TileCopyD(d);
191	            int64_t copyDNext = TileCopyD(d + 1);
192	
193	            // 先发下一个 tile 的 MTE2
194	            CopyInXTile(xTokenOff, (d + 1) * dimTile_, copyDNext);
195	
196	            // 等待当前 tile 就绪，Cast → phi 行双缓冲流水
197	            LocalTensor<T> xLocal = this->xInQueue_.template DeQue<T>();
198	            LocalTensor<float> xFp32 = this->xFp32Buf_.template Get<float>();
199	            Cast(xFp32, xLocal, RoundMode::CAST_NONE, static_cast<uint32_t>(N_ * copyD));
200	            PipeBarrier<PIPE_V>();
201	            this->xInQueue_.FreeTensor(xLocal);
202	
203	            PrefetchPhiRow(0, dimOff, copyD);
204	            for (int64_t row = 0; row < phiRows_ - 1; row++) {
205	                PrefetchPhiRow(row + 1, dimOff, copyD);
206	                ComputePhiDot(xFp32, xHat, LocalIdxOf(row), copyD, pipe_);
207	            }
208	            ComputePhiDot(xFp32, xHat, LocalIdxOf(phiRows_ - 1), copyD, pipe_);
209	        }
210	
211	        // 收尾：处理最后一个 tile
212	        {
213	            int64_t dimOff = (dimLoop_ - 1) * dimTile_;
214	            int64_t copyD = TileCopyD(dimLoop_ - 1);
215	            LocalTensor<T> xLocal = this->xInQueue_.template DeQue<T>();
216	            LocalTensor<float> xFp32 = this->xFp32Buf_.template Get<float>();
217	            Cast(xFp32, xLocal, RoundMode::CAST_NONE, static_cast<uint32_t>(N_ * copyD));
218	            PipeBarrier<PIPE_V>();
219	            this->xInQueue_.FreeTensor(xLocal);
220	
221	            PrefetchPhiRow(0, dimOff, copyD);
222	            for (int64_t row = 0; row < phiRows_ - 1; row++) {
223	                PrefetchPhiRow(row + 1, dimOff, copyD);
224	                ComputePhiDot(xFp32, xHat, LocalIdxOf(row), copyD, pipe_);
225	            }
226	            ComputePhiDot(xFp32, xHat, LocalIdxOf(phiRows_ - 1), copyD, pipe_);
227	        }
228	        // ComputePhiDot 末尾是 SetValue（标量写）+ FreeTensor，不发 V 指令，
229	        // Muls 不需要等待 V 流水 drain，无需 PipeBarrier
230	
231	        // xHat 乘以 invRms，完成 RMS norm
232	        int64_t xHatUsed = LocalIdxOf(phiRows_ - 1) + 1;
233	        Muls(xHat, xHat, invRms, static_cast<uint32_t>(xHatUsed));
234	        PipeBarrier<PIPE_V>();
235	
236	        LocalTensor<float> biasLocal = this->biasBuf_.template Get<float>();
237	
238	        // h_post 段：行 [0, N_)，xHat 本地下标 [0, N_)
239	        CopyInBias(biasLocal, 0, N_, pipe_);
240	        ComputeAndWriteHPost(tokenIdx, xHat, biasLocal, 0, N_, pipe_);
241	
242	        // h_res 段：行 [N_, phiRows_)，xHat 本地下标从 AlignUp(N_) 开始
243	        int64_t resCount = phiRows_ - N_;
244	        int64_t resLocalOff = AlignUp(N_);
245	        CopyInBias(biasLocal[resLocalOff], N_, resCount, pipe_);
246	        ComputeAndWriteHRes(tokenIdx, xHat, biasLocal, N_, resLocalOff, resCount, pipe_);
247	    }
248	
249	private:
250	    TPipe *pipe_ = nullptr;
251	    int64_t dimTile_ = 0;
252	    int64_t dimLoop_ = 0;
253	    int64_t baseT_ = 0;
254	    int64_t tailT_ = 0;
255	    int64_t coreTAct_ = 0;
256	};
257	
258	}  // namespace AiInfraMhcPreSplitPostRes
259	
260	#endif  // AI_INFRA_MHC_PRE_SPLIT_POST_RES_KERNEL_MULTI_TILE_H_
