// ========================================================================
// R9: MhcSandwichNormPostPreonly — entry point
//
// File structure:
//   ai_infra_mhc_sandwich_norm_post_preonly_common.h       — constants, type traits
//   ai_infra_mhc_sandwich_norm_post_preonly_kernel.h       — class: Init, Process, shared building blocks
