//   ai_infra_mhc_sandwich_norm_post_preonly_dualcore_mt.h  — ProcessTokenDualCoreMultiTile (multi-tile, D=5120)
//   ai_infra_mhc_sandwich_norm_post_preonly_singlecore.h   — ProcessToken + PhaseAB/C/D (fallback)
//   ai_infra_mhc_sandwich_norm_post_preonly.cpp            — this file (kernel entry point)
// ========================================================================

#include "ai_infra_mhc_sandwich_norm_post_preonly_kernel.h"

extern "C" __global__ __aicore__ void
ai_infra_mhc_sandwich_norm_post_preonly(GM_ADDR h_out, GM_ADDR residual, GM_ADDR h_post, GM_ADDR h_res, GM_ADDR phi,
                                        GM_ADDR alpha_0, GM_ADDR bias, GM_ADDR gamma_0, GM_ADDR gamma_1,
                                        GM_ADDR gamma_2, GM_ADDR h_in_prime, GM_ADDR x_2_out, GM_ADDR h_in_f32,
                                        GM_ADDR workspace, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_AIV_ONLY);

    if (workspace == nullptr) {
        return;
    }
    GM_ADDR usrWorkspace = GetUserWorkspace(workspace);
    if (usrWorkspace == nullptr) {
        return;
    }

    KernelAiInfraMhcSandwichNormPostPreonly<DTYPE_H_OUT> op;
    op.Init(h_out, residual, h_post, h_res, phi, alpha_0, bias, gamma_0, gamma_1, gamma_2, h_in_prime, x_2_out,
            h_in_f32, usrWorkspace, tiling);
    op.Process();
}

