    L2_DFX_PHASE_1(aclnnAiInfraMhcSandwichNormPostPreonly,
                   DFX_IN(hOut, residual, hPost, hRes, phi, alpha0, bias, gamma0, gamma1, gamma2Optional),
                   DFX_OUT(hInPrime, x2Out));
