47	        rowsPerCore_    = td.rowsPerCore;
48	        rowsPerCoreSp_  = td.rowsPerCoreSp;
49	        blockPivot_     = td.blockPivot;
50	        dimTile_        = td.dimTile;
51	        dimLoop_        = td.dimLoop;
52	        lastDimTile_    = td.lastDimTile;
53	        phiRows_        = td.phiRows;
54	        phiCols_        = td.phiCols;
55	        normEps_        = td.normEps;
56	        hcEps_          = td.hcEps;
57	        K_              = N_ * D_;
58	        invD_           = td.invD;
59	        invK_           = td.invK;
60	        useRmsMid_      = (td.useRmsMid != 0);
61	        coresPerToken_  = td.coresPerToken;
62	        myHeadCount_    = td.myHeadCount;
63	        maxTokensPerPair_ = td.maxTokensPerPair;
64	        syncGmOffsetFloats_ = td.syncGmOffsetFloats;
65	        returnHInF32_ = (td.returnHInF32 != 0);
66	
67	        const uint32_t blockIdx = GetBlockIdx();
68	        if (blockIdx >= usedCoreNum_) {
69	            tokenStart_ = 0;
70	            tokenEnd_ = 0;
71	            return;
72	        }
73	
74	        // ---- Core mapping ----
75	        if (coresPerToken_ == NUM_TWO) {
76	            coreRole_ = blockIdx % DUAL_CORE_COUNT;
77	            uint32_t pairIdx = blockIdx / DUAL_CORE_COUNT;
78	            headStart_ = coreRole_ * myHeadCount_;
79	
80	            uint32_t numPairs = usedCoreNum_ / NUM_TWO;
81	            if (numPairs == 0)
82	                numPairs = 1;
83	            if (pairIdx < blockPivot_) {
84	                tokenStart_ = pairIdx * rowsPerCoreSp_;
85	                tokenEnd_ = tokenStart_ + rowsPerCoreSp_;
86	            } else {
87	                tokenStart_ = blockPivot_ * rowsPerCoreSp_ + (pairIdx - blockPivot_) * rowsPerCore_;
88	                tokenEnd_ = tokenStart_ + rowsPerCore_;
89	            }
90	            uint64_t pairWsFloats = WS_HIN_BASE + (uint64_t)N_ * D_;
91	            pairWsBase_ = (uint64_t)pairIdx * pairWsFloats;
92	        } else {
93	            coreRole_ = 0;
94	            headStart_ = 0;
95	            if (blockIdx < blockPivot_) {
96	                tokenStart_ = blockIdx * rowsPerCoreSp_;
97	                tokenEnd_ = tokenStart_ + rowsPerCoreSp_;
98	            } else {
99	                tokenStart_ = blockPivot_ * rowsPerCoreSp_ + (blockIdx - blockPivot_) * rowsPerCore_;
100	                tokenEnd_ = tokenStart_ + rowsPerCore_;
101	            }
102	            uint64_t coreWsFloats = (uint64_t)(N_ + 1) * D_;
103	            pairWsBase_ = (uint64_t)blockIdx * coreWsFloats;
104	        }
105	        if (tokenEnd_ > totalTokens_)
106	            tokenEnd_ = totalTokens_;
107	
108	        // ---- GM tensors ----
109	        hOutGm_.SetGlobalBuffer((__gm__ T *)h_out_gm,         (uint64_t)totalTokens_ * D_);
110	        residualGm_.SetGlobalBuffer((__gm__ T *)residual_gm,  (uint64_t)totalTokens_ * N_ * D_);
111	        hPostGm_.SetGlobalBuffer((__gm__ float *)h_post_gm, (uint64_t)totalTokens_ * N_);
112	        hResGm_.SetGlobalBuffer((__gm__ float *)h_res_gm, (uint64_t)totalTokens_ * N_ * N_);
113	        phiGm_.SetGlobalBuffer((__gm__ float *)phi_gm,        (uint64_t)phiRows_ * phiCols_);
114	        alpha0Gm_.SetGlobalBuffer((__gm__ float *)alpha_0_gm, ALIGN8);
115	        biasGm_.SetGlobalBuffer((__gm__ float *)bias_gm,      ALIGN8);
116	        gamma0Gm_.SetGlobalBuffer((__gm__ float *)gamma_0_gm, D_);
117	        gamma1Gm_.SetGlobalBuffer((__gm__ float *)gamma_1_gm, D_);
118	        if (useRmsMid_) {
119	            gamma2Gm_.SetGlobalBuffer((__gm__ float *)gamma_2_gm, K_);
120	        }
121	        hInPrimeGm_.SetGlobalBuffer((__gm__ T *)h_in_prime_gm, (uint64_t)totalTokens_ * D_);
122	        x2OutGm_.SetGlobalBuffer((__gm__ T *)x_2_out_gm,      (uint64_t)totalTokens_ * N_ * D_);
123	        if (h_in_f32_gm != nullptr) {
124	            hInF32Gm_.SetGlobalBuffer((__gm__ float *)h_in_f32_gm, (uint64_t)totalTokens_ * D_);
125	        }
126	
127	        uint64_t maxPairWs = WS_HIN_BASE + (uint64_t)N_MAX * D_MAX;
128	        uint64_t maxSingleWs = (uint64_t)(N_MAX + 1) * D_MAX;
129	        uint64_t wsPerUnit = maxPairWs > maxSingleWs ? maxPairWs : maxSingleWs;
130	        workspaceGm_.SetGlobalBuffer((__gm__ float *)workspace, (uint64_t)usedCoreNum_ * wsPerUnit);
131	
132	        // ---- UB allocation ----
133	        uint32_t x2HeadCount = (coresPerToken_ == NUM_TWO) ? myHeadCount_ : N_;
134	        uint32_t resBatchSize = (coresPerToken_ == NUM_TWO) ? N_ : 2u;
135	        pipe_.InitBuffer(bufHOutBf16_,       1, dimTile_ * sizeof(T));
136	        pipe_.InitBuffer(bufHOutFp32_,          dimTile_ * sizeof(float));
137	        pipe_.InitBuffer(bufGamma0Fp32_,        dimTile_ * sizeof(float));
138	        pipe_.InitBuffer(bufGamma1Fp32_,        dimTile_ * sizeof(float));
139	        pipe_.InitBuffer(bufX2Fp32_,            x2HeadCount * dimTile_ * sizeof(float));
140	        pipe_.InitBuffer(bufOutFp32_,           dimTile_ * sizeof(float));
141	        pipe_.InitBuffer(bufResidualBf16_,   1, resBatchSize * dimTile_ * sizeof(T));
142	        pipe_.InitBuffer(bufResFp32_,           resBatchSize * dimTile_ * sizeof(float));
143	        pipe_.InitBuffer(bufSqFp32_,            dimTile_ * sizeof(float));
144	        pipe_.InitBuffer(bufPostComb_,          POST_COMB_SIZE * sizeof(float));
145	        pipe_.InitBuffer(bufPhiFp32_,  BUFFER_NUM_TWO, dimTile_ * sizeof(float));
146	        pipe_.InitBuffer(bufHInPrimeBf16_,   1, dimTile_ * sizeof(T));
147	        pipe_.InitBuffer(bufScalar_,            SCALAR_BUF_SIZE);
148	        pipe_.InitBuffer(bufReduceWork_,        dimTile_ * sizeof(float));
149	        pipe_.InitBuffer(bufGamma2Fp32_,        dimTile_ * sizeof(float));
150	
151	        // Sync workspace for dual-core sense-reversing barrier.
152	        // syncGmOffsetFloats_ is computed host-side in tiling as
153	        // `coreNumAiv * wsPerUnit_MAX` so kernel writes flags into exactly the
154	        // region host reserved (not into the middle of the data region).
155	        if (coresPerToken_ == NUM_TWO) {
156	            syncGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(
157	                (__gm__ float *)workspace + syncGmOffsetFloats_),
158	                (uint64_t)usedCoreNum_ * WS_SYNC_BLOCK);
159	            pipe_.InitBuffer(bufSyncUb_, 1, WS_SYNC_BLOCK * sizeof(int32_t));
160	        }
161	
162	        evtMte2toV_ = static_cast<int32_t>(pipe_.AllocEventID<HardEvent::MTE2_V>());
163	        evtMte3toV_ = static_cast<int32_t>(pipe_.AllocEventID<HardEvent::MTE3_V>());
164	        evtVtoMte3_ = static_cast<int32_t>(pipe_.AllocEventID<HardEvent::V_MTE3>());
165	        evtVtoMte2_ = static_cast<int32_t>(pipe_.AllocEventID<HardEvent::V_MTE2>());
166	    }
167	
168	    // =====================================================================
169	    //  Process: gamma hoisting + token loop dispatch
170	    // =====================================================================
171	    __aicore__ inline void Process()
172	    {
173	        if (tokenStart_ >= tokenEnd_) {
174	            return;
175	        }
176	        // Initialize sync flag slot to 0 (sense-reversing barrier)
177	        if (coresPerToken_ == NUM_TWO) {
178	            syncRound_ = 0;
179	            LocalTensor<int32_t> syncUb = bufSyncUb_.AllocTensor<int32_t>();
180	            for (uint32_t i = 0; i < WS_SYNC_BLOCK; ++i) {
181	                syncUb.SetValue(i, 0);
182	            }
183	            PipeBarrier<PIPE_V>();
184	            DataCopy(syncGm_[GetBlockIdx() * WS_SYNC_BLOCK], syncUb, WS_SYNC_BLOCK);
185	            PipeBarrier<PIPE_ALL>();
186	            bufSyncUb_.FreeTensor(syncUb);
187	        }
188	
189	        // Cache scalars
190	        alpha0_ = alpha0Gm_.GetValue(0);
191	        for (uint32_t i = 0; i < phiRows_ && i < N_MAX; ++i) {
192	            biasCache_[i] = biasGm_.GetValue(i);
193	        }
194	
195	        // Gamma hoisting: only for single-tile paths (dimLoop==1)
196	        if (dimLoop_ == 1) {
197	            DataCopyExtParams gP = {1, 0, 0, 0, 0};
198	            gP.blockLen = dimTile_ * sizeof(float);
199	            DataCopyPadExtParams<float> gPad = {false, 0, 0, 0};
200	            DataCopyPad(bufGamma0Fp32_.Get<float>(), gamma0Gm_[0], gP, gPad);
201	            DataCopyPad(bufGamma1Fp32_.Get<float>(), gamma1Gm_[0], gP, gPad);
202	            // gamma_2 is [N*D] — loaded per-head in RmsNormMid, not hoisted
203	        }
204	        
205	        SetFlag<HardEvent::MTE2_V>(evtMte2toV_);
206	        WaitFlag<HardEvent::MTE2_V>(evtMte2toV_);
207	
208	        // Dispatch
209	        for (uint32_t t = tokenStart_; t < tokenEnd_; ++t) {
210	            if (coresPerToken_ == NUM_TWO && dimLoop_ == 1)
211	                ProcessTokenDualCore(t);
212	            else if (coresPerToken_ == NUM_TWO && dimLoop_ > 1)
213	                ProcessTokenDualCoreMultiTile(t);
214	            else
215	                ProcessToken(t);
216	        }
217	
218	        pipe_.ReleaseEventID<HardEvent::MTE2_V>(evtMte2toV_);
219	        pipe_.ReleaseEventID<HardEvent::MTE3_V>(evtMte3toV_);
220	        pipe_.ReleaseEventID<HardEvent::V_MTE3>(evtVtoMte3_);
221	        pipe_.ReleaseEventID<HardEvent::V_MTE2>(evtVtoMte2_);
222	    }
223	
224	    // =================================================================
225	    //  Path-specific methods (implementations in separate headers)
226	    // =================================================================
227	private:
228	    __aicore__ inline void ProcessTokenDualCore(uint32_t token);
229	    __aicore__ inline void ProcessTokenDualCoreMultiTile(uint32_t token);
230	    __aicore__ inline void ProcessToken(uint32_t token);
231	
232	    // Single-core sub-phase helpers
233	    __aicore__ inline void PhaseAB_SingleTile(uint32_t token,
234	        const float (&postVals)[N_MAX], const float (&combVals)[N_MAX*N_MAX],
235	        float (&xHatVals)[N_MAX], float &sumSqPre);
236	    __aicore__ inline void PhaseAB_MultiTile(uint32_t token,
237	        const float (&postVals)[N_MAX], const float (&combVals)[N_MAX*N_MAX],
238	        float (&xHatVals)[N_MAX], float &sumSqPre);
239	    __aicore__ inline void PhaseC_HInAndX2Output(uint32_t token,
240	        const float (&gate)[N_MAX], float &sumSq1);
241	    __aicore__ inline void PhaseD_RmsNorm1Output(uint32_t token, float invRms1);
242	    __aicore__ __attribute__((noinline)) void Apply2BatchResidualAxpyTail(
243	        uint64_t rBaseTile, uint32_t tD,
244	        const float (&combVals)[N_MAX*N_MAX]);
245	
246	    // =================================================================
247	    //  Shared building blocks (被三条路径复用)
248	    // =================================================================
249	#include "ai_infra_mhc_sandwich_norm_post_preonly_kernel_compute.h"
250	#include "ai_infra_mhc_sandwich_norm_post_preonly_kernel_io.h"
251	
252	    // =================================================================
253	    //  Members
254	    // =================================================================
255	    TPipe pipe_;
256	
257	    // UB buffers
258	    TQue<TPosition::VECIN, 1>  bufHOutBf16_;
259	    TBuf<TPosition::VECCALC>   bufHOutFp32_;
260	    TBuf<TPosition::VECCALC>   bufGamma0Fp32_;
261	    TBuf<TPosition::VECCALC>   bufGamma1Fp32_;  // [R9] also x2[head0,tile0] store
262	    TBuf<TPosition::VECCALC>   bufGamma2Fp32_;  // [R9] also x2[head1,tile0] store
263	    TBuf<TPosition::VECCALC>   bufX2Fp32_;
264	    TBuf<TPosition::VECCALC>   bufOutFp32_;
265	    TQue<TPosition::VECIN, 1>  bufResidualBf16_;
266	    TBuf<TPosition::VECCALC>   bufResFp32_;
267	    TBuf<TPosition::VECCALC>   bufSqFp32_;
268	    TBuf<TPosition::VECCALC>   bufPostComb_;
269	    TQue<TPosition::VECIN, BUFFER_NUM_TWO>  bufPhiFp32_;
270	    TQue<TPosition::VECOUT, 1> bufHInPrimeBf16_;
271	    TBuf<TPosition::VECCALC>   bufScalar_;
272	    TBuf<TPosition::VECCALC>   bufReduceWork_;
273	    GlobalTensor<int32_t>      syncGm_;
274	    TQue<TPosition::VECIN, 1>  bufSyncUb_;
275	
276	    // GM tensors
277	    GlobalTensor<T>     hOutGm_, residualGm_, hInPrimeGm_, x2OutGm_;
278	    GlobalTensor<float> hPostGm_, hResGm_, phiGm_;
279	    GlobalTensor<float> alpha0Gm_, biasGm_;
280	    GlobalTensor<float> gamma0Gm_, gamma1Gm_, gamma2Gm_;
281	    GlobalTensor<float> hInF32Gm_;
282	    GlobalTensor<float> workspaceGm_;
283	
284	    // Tiling parameters
285	    uint32_t totalTokens_ = 0, N_ = 0, D_ = 0, K_ = 0;
286	    uint32_t usedCoreNum_ = 0, rowsPerCore_ = 0, rowsPerCoreSp_ = 0, blockPivot_ = 0;
287	    uint32_t dimTile_ = 0, dimLoop_ = 0, lastDimTile_ = 0;
288	    uint32_t phiRows_ = 0, phiCols_ = 0;
289	    float normEps_ = 1e-6f, hcEps_ = 1e-6f, invD_ = 0.0f, invK_ = 0.0f;
290	    uint32_t tokenStart_ = 0, tokenEnd_ = 0;
291	    float alpha0_ = 0.0f;
292	    float biasCache_[N_MAX] = {0.0f};
293	    uint64_t pairWsBase_ = 0;
294	    bool useRmsMid_ = false;
295	    bool returnHInF32_ = false;
296	
297	    // N-axis split
298	    uint32_t coresPerToken_ = 1;
299	    uint32_t myHeadCount_ = 0;
300	    uint32_t headStart_ = 0, coreRole_ = 0, maxTokensPerPair_ = 0;
301	
302	    // Sync region offset from host tiling
303	    uint32_t syncGmOffsetFloats_ = 0;
304	    uint32_t syncRound_ = 0;  // sense-reversing barrier round counter
305	
306	    int32_t evtMte2toV_ = 0;
307	    int32_t evtMte3toV_ = 0;
308	    int32_t evtVtoMte3_ = 0;
309	    int32_t evtVtoMte2_ = 0;
310	};
