11	// ========================================================================
12	// mhc_sandwich_norm_post_preonly_dualcore.h — single-tile dual-core path (D<=2560)
13	// v2: QuantizeRoundTrip at stage boundaries, N*D RMSNorm_mid, ReduceSumPrecise
14	// ========================================================================
15	#ifndef AI_INFRA_MHC_SANDWICH_NORM_POST_PREONLY_DUALCORE_H_
16	#define AI_INFRA_MHC_SANDWICH_NORM_POST_PREONLY_DUALCORE_H_
17	
18	template<typename T>
19	__aicore__ inline void KernelAiInfraMhcSandwichNormPostPreonly<T>::ProcessTokenDualCore(uint32_t token)
20	{
21	    const uint32_t D = D_, N = N_, myN = myHeadCount_, hStart = headStart_;
22	    const uint32_t tD = dimTile_;
23	    float postVals[N_MAX], combVals[N_MAX * N_MAX], xHatVals[N_MAX], gate[N_MAX];
24	    for (uint32_t i = 0; i < N; ++i) xHatVals[i] = 0.0f;
25	
26	    LoadTokenWeights(token, postVals, combVals);
27	
28	    // ---- Phase A: RMSNorm_0 (redundant on both cores) ----
29	    LoadHOutAndCast((uint64_t)token * D, tD);
30	
31	    // Start residual DMA in parallel with RMSNorm_0 compute
32	    {
33	        LocalTensor<T> resBf16 = bufResidualBf16_.AllocTensor<T>();
34	        uint64_t rBase = (uint64_t)token * N * D;
35	        for (uint32_t n = 0; n < N; ++n)
36	            DataCopy(resBf16[n * dimTile_], residualGm_[rBase + (uint64_t)n * D], tD);
37	        bufResidualBf16_.EnQue(resBf16);
38	    }
39	
40	    LocalTensor<float> hOutFp32 = bufHOutFp32_.Get<float>();
41	    float invRms0 = ComputeInvRms(ReduceSumSq(hOutFp32, tD), invD_);
42	    ApplyScaleAndGamma(hOutFp32, invRms0, bufGamma0Fp32_.Get<float>(), tD);
43	    // Stage 1 boundary: x1 → dtype → fp32
44	    QuantizeRoundTrip(hOutFp32, tD);
45	
46	    // Finish residual cast
47	    {
48	        LocalTensor<T> resBf16 = bufResidualBf16_.DeQue<T>();
49	        LocalTensor<float> resFp32 = bufResFp32_.Get<float>();
50	        for (uint32_t n = 0; n < N; ++n)
51	            Cast(resFp32[n * dimTile_], resBf16[n * dimTile_], RoundMode::CAST_NONE, tD);
52	        PipeBarrier<PIPE_V>();
53	        bufResidualBf16_.FreeTensor(resBf16);
54	    }
55	
56	    // ---- Phase B: MHC_Post (my N/2 heads) ----
57	    ComputeX2MyHeads(postVals, combVals, tD);
58	
59	    // Stage 2 boundary: x2 → dtype → fp32
60	    {
61	        LocalTensor<float> x2Tmp = bufX2Fp32_.Get<float>();
62	        for (uint32_t hi = 0; hi < myN; ++hi)
63	            QuantizeRoundTrip(x2Tmp[hi * dimTile_], tD);
64	    }
65	
66	    // ---- Optional RMSNorm_mid (over N*D: redundant computation of partner heads' sumSq) ----
67	    if (useRmsMid_) {
68	        LocalTensor<float> x2Fp32 = bufX2Fp32_.Get<float>();
69	        LocalTensor<float> hOutFp32 = bufHOutFp32_.Get<float>();  // still contains x1
70	        LocalTensor<float> resFp32 = bufResFp32_.Get<float>();    // still contains residual
71	
72	        // Compute sumSq for my N/2 heads
73	        float totalSumSqMid = 0.0f;
74	        for (uint32_t hi = 0; hi < myN; ++hi)
75	            totalSumSqMid += ReduceSumSq(x2Fp32[hi * dimTile_], tD);
76	
77	        // Compute sumSq for partner's N/2 heads (redundant computation, no sync needed)
78	        // Partner x2 also needs to be computed from quantized x1
79	        uint32_t partHStart = (coreRole_ == 0) ? myN : 0;
80	        LocalTensor<float> tmpBuf = bufOutFp32_.Get<float>();
81	        for (uint32_t ph = 0; ph < myN; ++ph) {
82	            uint32_t h = partHStart + ph;
83	            Muls(tmpBuf, hOutFp32, postVals[h], tD); PipeBarrier<PIPE_V>();
84	            for (uint32_t j = 0; j < N; ++j) {
85	                Axpy(tmpBuf, resFp32[j * dimTile_], combVals[j * N + h], tD);
86	                PipeBarrier<PIPE_V>();
87	            }
88	            // Quantize partner x2 before sumSq (same as my x2 was quantized)
89	            QuantizeRoundTrip(tmpBuf, tD);
90	            totalSumSqMid += ReduceSumSq(tmpBuf, tD);
91	        }
92	
93	        float invRmsMid = 1.0f / sqrt(totalSumSqMid * invK_ + normEps_);
94	        PipeBarrier<PIPE_ALL>();
95	
96	        // Apply: gamma_2 is [N*D], load gamma_2[hStart*D : (hStart+hi+1)*D] per head
97	        LocalTensor<float> gamma2 = bufGamma2Fp32_.Get<float>();
98	        for (uint32_t hi = 0; hi < myN; ++hi) {
99	            LoadGammaInto(gamma2, gamma2Gm_, (hStart + hi) * D, tD);
100	
101	            SetFlag<HardEvent::MTE2_V>(evtMte2toV_);
102	            WaitFlag<HardEvent::MTE2_V>(evtMte2toV_);
103	
104	            ApplyScaleAndGamma(x2Fp32[hi * dimTile_], invRmsMid, gamma2, tD);
105	            PipeBarrier<PIPE_ALL>();  // WAR: V-pipe must finish reading gamma2
106	                                      // before next iteration's MTE2 overwrites it
107	        }
108	
109	        // Stage 2.5 boundary: x2 → dtype → fp32
110	        for (uint32_t hi = 0; hi < myN; ++hi)
111	            QuantizeRoundTrip(x2Fp32[hi * dimTile_], tD);
112	    }
113	
114	    // ---- Phase C: sumSqPre + phi matmul ----
115	    LocalTensor<float> x2Fp32  = bufX2Fp32_.Get<float>();
116	    LocalTensor<float> outFp32 = bufOutFp32_.Get<float>();
117	    LocalTensor<float> sqBuf   = bufSqFp32_.Get<float>();
118	
119	    Mul(outFp32, x2Fp32, x2Fp32, tD);
120	    PipeBarrier<PIPE_V>();
121	    for (uint32_t hi = 1; hi < myN; ++hi) {
122	        Mul(sqBuf, x2Fp32[hi * dimTile_], x2Fp32[hi * dimTile_], tD);
123	        PipeBarrier<PIPE_V>();
124	        Add(outFp32, outFp32, sqBuf, tD);
125	        PipeBarrier<PIPE_V>();
126	    }
127	    float mySumSqPre = ReduceSumPrecise(outFp32, tD);
128	
129	    // phi matmul — double-buffer prefetch
130	    float myXHat[N_MAX];
131	    DataCopyExtParams cpP = {1, 0, 0, 0, 0};
132	    cpP.blockLen = tD * sizeof(float);
133	    DataCopyPadExtParams<float> cpPad = {true, 0, 0, 0};
134	
135	    const uint32_t totalPhiIters = phiRows_ * myN;
136	    {
137	        uint64_t phiOff = (uint64_t)0 * phiCols_ + (uint64_t)hStart * D;
138	        LocalTensor<float> phiBuf = bufPhiFp32_.AllocTensor<float>();
139	        DataCopyPad(phiBuf, phiGm_[phiOff], cpP, cpPad);
140	        bufPhiFp32_.EnQue(phiBuf);
141	    }
142	    for (uint32_t iter = 0; iter < totalPhiIters; ++iter) {
143	        uint32_t o = iter / myN, hi = iter % myN;
144	        if (iter + 1 < totalPhiIters) {
145	            uint32_t nO = (iter+1)/myN, nHi = (iter+1)%myN;
146	            uint64_t nOff = (uint64_t)nO * phiCols_ + (uint64_t)(hStart + nHi) * D;
147	            LocalTensor<float> phiNext = bufPhiFp32_.AllocTensor<float>();
148	            DataCopyPad(phiNext, phiGm_[nOff], cpP, cpPad);
149	            bufPhiFp32_.EnQue(phiNext);
150	        }
151	        LocalTensor<float> phiCur = bufPhiFp32_.DeQue<float>();
152	        if (hi == 0) { Mul(outFp32, x2Fp32, phiCur, tD); PipeBarrier<PIPE_V>(); }
153	        else { Mul(sqBuf, x2Fp32[hi*dimTile_], phiCur, tD); PipeBarrier<PIPE_V>();
154	               Add(outFp32, outFp32, sqBuf, tD); PipeBarrier<PIPE_V>(); }
155	        bufPhiFp32_.FreeTensor(phiCur);
156	        if (hi == myN - 1) {
157	            myXHat[o] = ReduceSumPrecise(outFp32, tD);
158	        }
159	    }
160	
161	    // ---- SYNC: scalars + x2 exchange ----
162	    uint32_t myX2WsSlot = WS_HIN_BASE + coreRole_ * myN * D;
163	    DualCoreSyncExchange(mySumSqPre, myXHat, mySumSqPre, xHatVals);
164	    WriteX2ToWorkspace(tD, 0, x2Fp32, myN, myX2WsSlot);
165	    float totalSumSqPre;
166	    SyncAndReadPartner(mySumSqPre, myXHat, totalSumSqPre, xHatVals);
167	
168	    // ---- ComputeGate ----
169	    ComputeGateValues(totalSumSqPre, xHatVals, gate);
170	
171	    // ---- Phase D: h_in (my + partner heads) ----
172	    Muls(outFp32, x2Fp32, gate[hStart], tD);
173	    PipeBarrier<PIPE_V>();
174	    for (uint32_t hi = 1; hi < myN; ++hi) {
175	        Axpy(outFp32, x2Fp32[hi * dimTile_], gate[hStart + hi], tD);
176	        PipeBarrier<PIPE_V>();
177	    }
178	
179	    // Partner x2 reads + my x2_out writes (MTE2/MTE3 overlap)
180	    uint32_t partnerHStart = (coreRole_ == 0) ? myN : 0;
181	    uint64_t x2OutBase = (uint64_t)token * N * D;
182	    for (uint32_t hi = 0; hi < myN; ++hi) {
183	        ReadPartnerX2Tile(sqBuf, hi, 0, tD);
184	        WriteX2OutTile(x2Fp32[hi * dimTile_], x2OutBase + (uint64_t)(hStart + hi) * D, tD);
185	        Axpy(outFp32, sqBuf, gate[partnerHStart + hi], tD);
186	        PipeBarrier<PIPE_V>();
187	        SetFlag<HardEvent::V_MTE2>(evtVtoMte2_);
188	        WaitFlag<HardEvent::V_MTE2>(evtVtoMte2_);
189	    }
190	
191	    // ---- Phase E: RMSNorm_1 ----
192	    // Flush MTE3 from WriteX2OutTile — WAR with QuantizeRoundTrip
193	    // Stage 3 boundary: h_in → dtype → fp32
194	    QuantizeRoundTrip(outFp32, tD);
195	    float sumSq1 = ReduceSumSq(outFp32, tD);
196	    float invRms1 = ComputeInvRms(sumSq1, invD_);
197	
198	    if (coreRole_ == 0) {
199	        ApplyScaleAndGamma(outFp32, invRms1, bufGamma1Fp32_.Get<float>(), tD);
200	        WriteHInPrimeTile(outFp32, (uint64_t)token * D, tD);
201	    }
202	}
203	
204	#endif // AI_INFRA_MHC_SANDWICH_NORM_POST_PREONLY_DUALCORE_H_
