34	        scBuf.SetValue(1 + o, myXHat[o]);
35	    for (uint32_t i = 1 + phiRows_; i < WS_SYNC_BLOCK; ++i)
36	        scBuf.SetValue(i, 0.0f);
37	    PipeBarrier<PIPE_V>();
38	
39	    // Write scalars
40	    DataCopyExtParams wp = {1, 0, 0, 0, 0};
41	    wp.blockLen = WS_SYNC_BLOCK * sizeof(float);
42	    DataCopyPad(workspaceGm_[pairWsBase_ + mySync1Slot], scBuf, wp);
43	}
