45	/// Write x2 from UB to workspace GM (for partner to read)
46	__aicore__ inline void WriteX2ToWorkspace(uint32_t tD, uint32_t tOff,
47	    LocalTensor<float> x2Src, uint32_t numHeads, uint32_t wsSlot)
48	{
49	    for (uint32_t hi = 0; hi < numHeads; ++hi) {
50	        DataCopyExtParams wp = {1, 0, 0, 0, 0};
51	        wp.blockLen = tD * sizeof(float);
52	        DataCopyPad(workspaceGm_[pairWsBase_ + wsSlot + (uint64_t)hi * D_ + tOff],
53	                    x2Src[hi * dimTile_], wp);
54	    }
55	}
56	
57	// ---- Sense-reversing barrier (write-own-only) ----
58	// Replaces IBSet/IBWait to eliminate cross-core GM writes (mssanitizer OOB).
59	// Each core only writes to its own flag; reads partner's flag via spin.
60	// Polarity flips each round (0→1→0→...) so no reset/clear phase is needed.
61	
62	/// Sense-reversing barrier: signal own readiness + wait for partner.
63	/// Each core writes ONLY to syncGm_[ownBlockIdx], reads partner's slot.
64	__aicore__ inline void SyncBarrier(uint32_t partnerBlockIdx)
65	{
66	    int32_t syncVal = (syncRound_ & 1) ? 0 : 1;
67	    uint32_t mySlot   = GetBlockIdx() * WS_SYNC_BLOCK;
68	    uint32_t partSlot = partnerBlockIdx * WS_SYNC_BLOCK;
69	
70	    // Signal: write syncVal to own slot
71	    LocalTensor<int32_t> syncUb = bufSyncUb_.AllocTensor<int32_t>();
72	    syncUb.SetValue(0, syncVal);
73	    for (uint32_t i = 1; i < WS_SYNC_BLOCK; ++i) syncUb.SetValue(i, 0);
74	    PipeBarrier<PIPE_V>();
75	    DataCopy(syncGm_[mySlot], syncUb, WS_SYNC_BLOCK);
76	    PipeBarrier<PIPE_ALL>();
77	    bufSyncUb_.FreeTensor(syncUb);
78	
79	    // Wait: spin-read partner's slot until syncVal
80	    syncUb = bufSyncUb_.AllocTensor<int32_t>();
81	    // 一个手写Barrier，用来在处理一个token的两个核之间做同步：
82	    // 1. 每个核把 syncVal 写进GM上自己的slot；
83	    // 2.while循环不停地从GM读对方核的slot到UB，直到它等于本轮的syncVal；
84	    // 3. 一旦读到对方的值，说明对方达到屏障点，跳出，双核对齐。
85	    while (true) {
86	        DataCopy(syncUb, syncGm_[partSlot], WS_SYNC_BLOCK);
87	        PipeBarrier<PIPE_ALL>();
88	        if (syncUb.GetValue(0) == syncVal) {
89	            break;
90	        }
91	    }
92	    bufSyncUb_.FreeTensor(syncUb);
93	
94	    syncRound_++;
95	}
96	
97	/// Sync + read partner's sync block, combine partials.
98	__aicore__ inline void SyncAndReadPartner(
99	    float mySumSqPre, const float (&myXHat)[N_MAX],
100	    float &totalSumSqPre, float (&xHatVals)[N_MAX])
101	{
102	    uint32_t partnerBlockIdx = (coreRole_ == 0) ? (GetBlockIdx() + 1) : (GetBlockIdx() - 1);
103	    uint32_t partSync1Slot   = (coreRole_ == 0) ? WS_SYNC1_CORE1 : WS_SYNC1_CORE0;
104	
105	    PipeBarrier<PIPE_ALL>();
106	    SyncBarrier(partnerBlockIdx);
107	
108	    // Read partner's sync1 block
109	    LocalTensor<float> scBuf = bufScalar_.Get<float>();
110	    DataCopyExtParams rp = {1, 0, 0, 0, 0};
111	    rp.blockLen = WS_SYNC_BLOCK * sizeof(float);
112	    DataCopyPadExtParams<float> rpad = {false, 0, 0, 0};
113	    DataCopyPad(scBuf, workspaceGm_[pairWsBase_ + partSync1Slot], rp, rpad);
114	    PipeBarrier<PIPE_ALL>();
115	
116	    totalSumSqPre = mySumSqPre + scBuf.GetValue(0);
117	    for (uint32_t o = 0; o < phiRows_; ++o)
118	        xHatVals[o] = myXHat[o] + scBuf.GetValue(1 + o);
119	}
