122	/// In-place quantize round-trip: fp32 → io_dtype → fp32
123	/// Simulates stage-boundary dtype truncation to match golden
124	__aicore__ inline void QuantizeRoundTrip(LocalTensor<float> buf, uint32_t count)
125	{
126	    LocalTensor<T> tmp = bufHInPrimeBf16_.AllocTensor<T>();
127	    CastToIO(tmp, buf, count);
128	    PipeBarrier<PIPE_V>();  // RAW on tmp: CastToIO must finish writing before Cast reads
129	    Cast(buf, tmp, RoundMode::CAST_NONE, count);
130	    PipeBarrier<PIPE_V>();
131	    bufHInPrimeBf16_.FreeTensor(tmp);
132	}
