139	    DataCopyExtParams rp = {1, 0, 0, 0, 0};
140	    rp.blockLen = tD * sizeof(float);
141	    DataCopyPadExtParams<float> rpad = {false, 0, 0, 0};
142	    DataCopyPad(dst, workspaceGm_[pairWsBase_ + partnerX2WsSlot +
143	                (uint64_t)hi * D_ + tOff], rp, rpad);
