11	// ========================================================================
12	// mhc_sandwich_norm_post_preonly_dualcore_mt.h -- multi-tile dual-core path (D=5120)
13	// v2: QuantizeRoundTrip at stage boundaries, N*D RMSNorm_mid, ReduceSumPrecise
14	//
15	// x2 storage in UB (no GM workspace for tile spill):
16	//   tile 0: head0 -> bufGamma1Fp32_, head1 -> bufGamma2Fp32_
17	//   tile 1: head0..1 -> bufX2Fp32_
18	//
19	// h_in storage in UB:
20	//   tile 0 -> bufHOutFp32_, tile 1 -> bufOutFp32_
21	//
22	// RMSNorm_mid uses redundant computation: each core computes ALL N heads'
23	// sumSq independently using already-loaded x1 and residual data, avoiding
24	// the need for cross-core synchronization.
25	// ========================================================================
26	#ifndef AI_INFRA_MHC_SANDWICH_NORM_POST_PREONLY_DUALCORE_MT_H_
27	#define AI_INFRA_MHC_SANDWICH_NORM_POST_PREONLY_DUALCORE_MT_H_
28	
29	template<typename T>
30	__aicore__ inline void KernelAiInfraMhcSandwichNormPostPreonly<T>::ProcessTokenDualCoreMultiTile(uint32_t token)
31	{
32	    const uint32_t D = D_, N = N_, myN = myHeadCount_, hStart = headStart_;
33	    float postVals[N_MAX], combVals[N_MAX * N_MAX];
34	    float xHatVals[N_MAX], gate[N_MAX];
35	    float totalSumSqMid = 0.0f;
36	    for (uint32_t i = 0; i < N; ++i) { xHatVals[i] = 0.0f; }
37	
38	    LoadTokenWeights(token, postVals, combVals);
39	
40	    // ===== Pass 1: RMSNorm_0 sum-of-squares =====
41	    float sumSq0 = 0.0f;
42	    for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
43	        uint32_t tD = GetTileD(tile);
44	        LoadHOutAndCast((uint64_t)token * D + tile * dimTile_, tD);
45	        sumSq0 += ReduceSumSq(bufHOutFp32_.Get<float>(), tD);
46	    }
47	    float invRms0 = ComputeInvRms(sumSq0, invD_);
48	
49	    // ===== Pass 2: Normalize + MHC_Post + store x2 in UB =====
50	    // Also accumulate totalSumSqMid for RMSNorm_mid (redundant computation of
51	    // partner's heads to avoid cross-core sync)
52	    for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
53	        uint32_t tD = GetTileD(tile), tOff = tile * dimTile_;
54	
55	        LoadHOutAndCast((uint64_t)token * D + tOff, tD);
56	
57	        // Load gamma_0 for this tile
58	        LocalTensor<float> gammaFp32 = bufGamma0Fp32_.Get<float>();
59	        LoadGammaInto(gammaFp32, gamma0Gm_, tOff, tD);
60	
61	        SetFlag<HardEvent::MTE2_V>(evtMte2toV_);
62	        WaitFlag<HardEvent::MTE2_V>(evtMte2toV_);
63	
64	        ApplyScaleAndGamma(bufHOutFp32_.Get<float>(), invRms0, gammaFp32, tD);
65	        // Stage 1 boundary: x1 → dtype → fp32
66	        QuantizeRoundTrip(bufHOutFp32_.Get<float>(), tD);
67	
68	        LoadResidualAndCast((uint64_t)token * N * D + tOff, tD);
69	        ComputeX2MyHeads(postVals, combVals, tD);
70	
71	        // Stage 2 boundary: quantize x2 per head
72	        {
73	            LocalTensor<float> x2Fp32 = bufX2Fp32_.Get<float>();
74	            for (uint32_t hi = 0; hi < myN; ++hi)
75	                QuantizeRoundTrip(x2Fp32[hi * dimTile_], tD);
76	        }
77	
78	        // Accumulate sumSqMid for RMSNorm_mid (my heads + partner heads redundant)
79	        if (useRmsMid_) {
80	            LocalTensor<float> x2Fp32 = bufX2Fp32_.Get<float>();
81	            // My N/2 heads
82	            for (uint32_t hi = 0; hi < myN; ++hi) {
83	                totalSumSqMid += ReduceSumSq(x2Fp32[hi * dimTile_], tD);
84	            } 
85	
86	            // Partner's N/2 heads (redundant computation, no sync needed)
87	            // x1 is in bufHOutFp32_, residual is in bufResFp32_
88	            uint32_t partHStart = (coreRole_ == 0) ? myN : 0;
89	            LocalTensor<float> tmpBuf = bufOutFp32_.Get<float>();
90	            LocalTensor<float> hOutFp32 = bufHOutFp32_.Get<float>();
91	            LocalTensor<float> resFp32 = bufResFp32_.Get<float>();
92	            for (uint32_t ph = 0; ph < myN; ++ph) {
93	                uint32_t h = partHStart + ph;
94	                Muls(tmpBuf, hOutFp32, postVals[h], tD); PipeBarrier<PIPE_V>();
95	                for (uint32_t j = 0; j < N; ++j) {
96	                    Axpy(tmpBuf, resFp32[j * dimTile_], combVals[j * N + h], tD);
97	                    PipeBarrier<PIPE_V>();
98	                }
99	                // Quantize partner x2 (matches partner's Stage 2 boundary)
100	                QuantizeRoundTrip(tmpBuf, tD);
101	                totalSumSqMid += ReduceSumSq(tmpBuf, tD);
102	            }
103	        }
104	
105	        // Store x2 into UB slots
106	        if (tile == 0) {
107	            LocalTensor<float> x2Fp32 = bufX2Fp32_.Get<float>();
108	            Adds(bufGamma1Fp32_.Get<float>(), x2Fp32[0], 0.0f, tD);
109	            PipeBarrier<PIPE_V>();
110	            Adds(bufGamma2Fp32_.Get<float>(), x2Fp32[dimTile_], 0.0f, tD);
111	            PipeBarrier<PIPE_V>();
112	        }
113	        // tile 1: x2 stays in bufX2Fp32_
114	    }
115	
116	    // ===== [Optional] RMSNorm_mid (apply normalization) =====
117	    if (useRmsMid_) {
118	        float invRmsMid = 1.0f / sqrt(totalSumSqMid * invK_ + normEps_);
119	
120	        for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
121	            uint32_t tD = GetTileD(tile), tOff = tile * dimTile_;
122	            for (uint32_t hi = 0; hi < myN; ++hi) {
123	                // gamma_2 is [N*D]: load gamma_2[(hStart+hi)*D + tOff]
124	                LocalTensor<float> gammaFp32 = bufGamma0Fp32_.Get<float>();
125	                LoadGammaInto(gammaFp32, gamma2Gm_, (hStart + hi) * D + tOff, tD);
126	
127	                SetFlag<HardEvent::MTE2_V>(evtMte2toV_);
128	                WaitFlag<HardEvent::MTE2_V>(evtMte2toV_);
129	
130	                ApplyScaleAndGamma(GetX2HeadTile(tile, hi), invRmsMid, gammaFp32, tD);
131	                PipeBarrier<PIPE_ALL>();
132	            }
133	        }
134	
135	        // Stage 2.5 boundary: quantize x2 per head per tile
136	        for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
137	            uint32_t tD = GetTileD(tile);
138	            for (uint32_t hi = 0; hi < myN; ++hi)
139	                QuantizeRoundTrip(GetX2HeadTile(tile, hi), tD);
140	        }
141	    }
142	
143	    // ===== Phase C: sumSqPre + phi matmul =====
144	    float mySumSqPre = 0.0f;
145	    for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
146	        uint32_t tD = GetTileD(tile), tOff = tile * dimTile_;
147	        LocalTensor<float> outFp32 = bufOutFp32_.Get<float>();
148	        LocalTensor<float> sqBuf   = bufSqFp32_.Get<float>();
149	
150	        // sumSqPre partial
151	        { LocalTensor<float> x2h0 = GetX2HeadTile(tile, 0);
152	          Mul(outFp32, x2h0, x2h0, tD); PipeBarrier<PIPE_V>(); }
153	        for (uint32_t hi = 1; hi < myN; ++hi) {
154	            LocalTensor<float> x2hi = GetX2HeadTile(tile, hi);
155	            Mul(sqBuf, x2hi, x2hi, tD); PipeBarrier<PIPE_V>();
156	            Add(outFp32, outFp32, sqBuf, tD); PipeBarrier<PIPE_V>();
157	        }
158	        mySumSqPre += ReduceSumPrecise(outFp32, tD);
159	
160	        // phi matmul partial
161	        DataCopyExtParams cpP = {1, 0, 0, 0, 0};
162	        cpP.blockLen = tD * sizeof(float);
163	        DataCopyPadExtParams<float> cpPad = {true, 0, 0, 0};
164	        for (uint32_t o = 0; o < phiRows_; ++o) {
165	            for (uint32_t hi = 0; hi < myN; ++hi) {
166	                uint64_t phiOff = (uint64_t)o * phiCols_ + (uint64_t)(hStart + hi) * D + tOff;
167	                LocalTensor<float> phiBuf = bufPhiFp32_.AllocTensor<float>();
168	                DataCopyPad(phiBuf, phiGm_[phiOff], cpP, cpPad);
169	                bufPhiFp32_.EnQue(phiBuf);
170	                phiBuf = bufPhiFp32_.DeQue<float>();
171	                LocalTensor<float> x2hi = GetX2HeadTile(tile, hi);
172	                if (hi == 0) { Mul(outFp32, x2hi, phiBuf, tD); PipeBarrier<PIPE_V>(); }
173	                else { Mul(sqBuf, x2hi, phiBuf, tD); PipeBarrier<PIPE_V>();
174	                       Add(outFp32, outFp32, sqBuf, tD); PipeBarrier<PIPE_V>(); }
175	                bufPhiFp32_.FreeTensor(phiBuf);
176	            }
177	            xHatVals[o] += ReduceSumPrecise(outFp32, tD);
178	        }
179	    }
180	
181	    // ===== SYNC + Gate =====
182	    float myXHat[N_MAX];
183	    for (uint32_t o = 0; o < phiRows_; ++o) myXHat[o] = xHatVals[o];
184	
185	    uint32_t myX2WsSlot = WS_HIN_BASE + coreRole_ * myN * D;
186	    DualCoreSyncExchange(mySumSqPre, myXHat, mySumSqPre, xHatVals);
187	
188	    // Write my x2 to workspace per tile
189	    for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
190	        uint32_t tD = GetTileD(tile), tOff = tile * dimTile_;
191	        for (uint32_t hi = 0; hi < myN; ++hi) {
192	            LocalTensor<float> x2hi = GetX2HeadTile(tile, hi);
193	            DataCopyExtParams wp = {1, 0, 0, 0, 0};
194	            wp.blockLen = tD * sizeof(float);
195	            DataCopyPad(workspaceGm_[pairWsBase_ + myX2WsSlot + (uint64_t)hi * D + tOff],
196	                        x2hi, wp);
197	        }
198	    }
199	
200	    float totalSumSqPre;
201	    SyncAndReadPartner(mySumSqPre, myXHat, totalSumSqPre, xHatVals);
202	    ComputeGateValues(totalSumSqPre, xHatVals, gate);
203	
204	    // ===== Phase D: h_in + x2_out + RMSNorm_1 (2-pass) =====
205	    uint32_t partnerHStart = (coreRole_ == 0) ? myN : 0;
206	    float sumSq1 = 0.0f;
207	
208	    // Pass 1: compute h_in per tile, accumulate sumSq1
209	    for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
210	        uint32_t tD = GetTileD(tile), tOff = tile * dimTile_;
211	        // h_in dest: tile0->hOutFp32, tile1->outFp32
212	        LocalTensor<float> hInDst = (tile == 0) ?
213	            bufHOutFp32_.Get<float>() : bufOutFp32_.Get<float>();
214	
215	        { LocalTensor<float> x2h0 = GetX2HeadTile(tile, 0);
216	          Muls(hInDst, x2h0, gate[hStart], tD); PipeBarrier<PIPE_V>(); }
217	        for (uint32_t hi = 1; hi < myN; ++hi) {
218	            LocalTensor<float> x2hi = GetX2HeadTile(tile, hi);
219	            Axpy(hInDst, x2hi, gate[hStart + hi], tD); PipeBarrier<PIPE_V>();
220	        }
221	
222	        // Write x2_out for my heads
223	        uint64_t x2OutBase = (uint64_t)token * N * D + tOff;
224	        for (uint32_t hi = 0; hi < myN; ++hi)
225	            WriteX2OutTile(GetX2HeadTile(tile, hi),
226	                           x2OutBase + (uint64_t)(hStart + hi) * D, tD);
227	
228	        // Add partner x2 contribution
229	        LocalTensor<float> sqBuf = bufSqFp32_.Get<float>();
230	        for (uint32_t hi = 0; hi < myN; ++hi) {
231	            ReadPartnerX2Tile(sqBuf, hi, tOff, tD);
232	            Axpy(hInDst, sqBuf, gate[partnerHStart + hi], tD);
233	            PipeBarrier<PIPE_V>();
234	            SetFlag<HardEvent::V_MTE2>(evtVtoMte2_);
235	            WaitFlag<HardEvent::V_MTE2>(evtVtoMte2_);
236	        }
237	
238	        // Stage 3 boundary: h_in → dtype → fp32
239	        QuantizeRoundTrip(hInDst, tD);
240	
241	        sumSq1 += ReduceSumSq(hInDst, tD);
242	    }
243	
244	    // Pass 2: RMSNorm_1 + output (core0 only)
245	    float invRms1 = ComputeInvRms(sumSq1, invD_);
246	    if (coreRole_ == 0) {
247	        for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
248	            uint32_t tD = GetTileD(tile), tOff = tile * dimTile_;
249	            LocalTensor<float> hInSrc = (tile == 0) ?
250	                bufHOutFp32_.Get<float>() : bufOutFp32_.Get<float>();
251	            LocalTensor<float> gammaFp32 = bufGamma0Fp32_.Get<float>();
252	            LoadGammaInto(gammaFp32, gamma1Gm_, tOff, tD);
253	            PipeBarrier<PIPE_ALL>();
254	            ApplyScaleAndGamma(hInSrc, invRms1, gammaFp32, tD);
255	            WriteHInPrimeTile(hInSrc, (uint64_t)token * D + tOff, tD);
256	        }
257	    }
258	}
259	
260	#endif // AI_INFRA_MHC_SANDWICH_NORM_POST_PREONLY_DUALCORE_MT_H_
