9	*/
10	
11	#include "ai_infra_mhc_sandwich_norm_post_preonly_tiling.h"
12	#include <algorithm>
13	#include "register/op_impl_registry.h"
14	#include "tiling/platform/platform_ascendc.h"
15	#include "log/log.h"
16	#include "error/ops_error.h"
17	
18	namespace optiling {
19	
20	// Host-side constants (mirrors op_kernel/mhc_sandwich_norm_post_preonly_common.h)
21	constexpr uint32_t HOST_D_MAX             = 5120;
22	constexpr uint32_t HOST_N_MAX             = 4;
23	constexpr uint32_t HOST_D_TILE_MAX        = 2560;
24	constexpr uint32_t HOST_D_TILE_ALIGN_ELEM = 128;
25	constexpr uint32_t HOST_DUAL_CORE_COUNT   = 2;
26	constexpr uint32_t HOST_MAX_TOKENS        = 1024 * 1024;    // B*S 上限
27	constexpr uint32_t HOST_WS_HIN_BASE       = 16;    // workspace pair header (sync blocks)
28	constexpr uint32_t HOST_WS_SYNC_BLOCK     = 8;     // floats per sync block
29	constexpr uint32_t HOST_WS_NUM_EVENTS     = 1;     // sense-reversing barrier: 1 flag per core
30	constexpr uint32_t NUM_ONE = 1;
31	constexpr uint32_t NUM_TWO = 2;
32	constexpr size_t   HOST_MIN_WORKSPACE     = 64;    // 最小 workspace 字节数
33	
34	static ge::graphStatus TilingAiInfraMhcSandwichNormPostPreonly(gert::TilingContext *context)
35	{
36	    // --- Platform info ---
37	    auto platformInfo = context->GetPlatformInfo();
38	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
39	    uint32_t coreNumAiv = ascendcPlatform.GetCoreNumAiv();
40	    if (coreNumAiv == 0) coreNumAiv = 1;
41	
42	    // --- Get shapes (support both [B,S,D]/[T,D] and [B,S,N,D]/[T,N,D]) ---
43	    auto h_out_shape = context->GetInputShape(0);  // [B,S,D] or [T,D]
44	    auto res_shape = context->GetInputShape(1);     // [B,S,N,D] or [T,N,D]
45	    auto phi_shape = context->GetInputShape(4);     // [N, N*D]
46	    if (h_out_shape == nullptr || res_shape == nullptr || phi_shape == nullptr) {
47	        OPS_LOG_E("AiInfraMhcSandwichNormPostPreonly",
48	                  "GetInputShape is return nullptr");
49	        return ge::GRAPH_FAILED;
50	    }
51	    
52	    const auto &hs = h_out_shape->GetStorageShape();
53	    const auto &rs = res_shape->GetStorageShape();
54	    const auto &ps = phi_shape->GetStorageShape();
55	
56	    // --- Format consistency: residual.ndim must be h_out.ndim + 1 ---
57	    size_t hDimNum = hs.GetDimNum();
58	    size_t rDimNum = rs.GetDimNum();
59	    if (hDimNum != 2U && hDimNum != 3U) {
60	        OPS_LOG_E("AiInfraMhcSandwichNormPostPreonly",
61	                  "h_out must be 2D [T,D] or 3D [B,S,D], got %zuD", hDimNum);
62	        return ge::GRAPH_FAILED;
63	    }
64	    if (rDimNum != hDimNum + 1U) {
65	        OPS_LOG_E("AiInfraMhcSandwichNormPostPreonly",
66	                  "residual.ndim (%zu) must be h_out.ndim (%zu) + 1", rDimNum, hDimNum);
67	        return ge::GRAPH_FAILED;
68	    }
69	
70	    uint32_t totalTokens;
71	    uint32_t D;
72	    uint32_t N;
73	    if (hDimNum == 2U) {
74	        // [T, D] format
75	        totalTokens = static_cast<uint32_t>(hs.GetDim(0));
76	        D = static_cast<uint32_t>(hs.GetDim(1));
77	        N = static_cast<uint32_t>(rs.GetDim(1));  // [T, N, D]
78	    } else {
79	        // [B, S, D] format
80	        uint32_t B = static_cast<uint32_t>(hs.GetDim(0));
81	        uint32_t S = static_cast<uint32_t>(hs.GetDim(1));
82	        D = static_cast<uint32_t>(hs.GetDim(NUM_TWO));
83	        N = static_cast<uint32_t>(rs.GetDim(NUM_TWO));  // [B, S, N, D]
84	        totalTokens = B * S;
85	    }
86	
87	    uint32_t phiRows = static_cast<uint32_t>(ps.GetDim(0));  // N (pre-branch only)
88	    uint32_t phiCols = static_cast<uint32_t>(ps.GetDim(1));  // N*D
89	
90	    // --- Parameter validation ---
91	    if (totalTokens == 0 || totalTokens > HOST_MAX_TOKENS) {
92	        OPS_LOG_E("AiInfraMhcSandwichNormPostPreonly",
93	                  "totalTokens (B*S) must be in [1, %u], got %u", HOST_MAX_TOKENS, totalTokens);
94	        return ge::GRAPH_FAILED;
95	    }
96	    if (N != HOST_N_MAX) {
97	        OPS_LOG_E("AiInfraMhcSandwichNormPostPreonly",
98	                  "headCount (N) must be %u, got %u", HOST_N_MAX, N);
99	        return ge::GRAPH_FAILED;
100	    }
101	    if (D != HOST_D_TILE_MAX && D != HOST_D_MAX) {
102	        OPS_LOG_E("AiInfraMhcSandwichNormPostPreonly",
103	                  "embedDim (D) must be %u or %u, got %u", HOST_D_TILE_MAX, HOST_D_MAX, D);
104	        return ge::GRAPH_FAILED;
105	    }
106	
107	    // --- Attributes (all optional with defaults) ---
108	    const gert::RuntimeAttrs *attrs = context->GetAttrs();
109	    float normEps = 1e-6F;
110	    float hcEps = 1e-6F;
111	    bool returnHInF32 = false;
112	    if (attrs != nullptr) {
113	        // With op_host_aclnn (auto-generated aclnn wrapper), attrs are stored as float
114	        // matching the .Float() declaration in _def.cpp.
115	        const float *eps0 = attrs->GetAttrPointer<float>(0);
116	        if (eps0 != nullptr) {
117	            normEps = *eps0;
118	        }
119	        const float *eps1 = attrs->GetAttrPointer<float>(1);
120	        if (eps1 != nullptr) {
121	            hcEps = *eps1;
122	        }
123	
124	        const bool *returnHInF32Ptr = attrs->GetBool(2);
125	        if (returnHInF32Ptr != nullptr) {
126	            returnHInF32 = *returnHInF32Ptr;
127	        }
128	    }
129	
130	    // --- Validate eps ---
131	    if (normEps < 0.0F) {
132	        OPS_LOG_E("AiInfraMhcSandwichNormPostPreonly", "norm_eps must be >= 0, got %e", normEps);
133	        return ge::GRAPH_FAILED;
134	    }
135	    if (hcEps < 0.0F) {
136	        OPS_LOG_E("AiInfraMhcSandwichNormPostPreonly", "hc_eps must be >= 0, got %e", hcEps);
137	        return ge::GRAPH_FAILED;
138	    }
139	
140	    // --- Detect gamma_2 optional input (index 9) ---
141	    // If gamma_2 is provided, enable RMSNorm_mid; otherwise skip it
142	    auto gamma2_shape = context->GetOptionalInputShape(9);
143	    bool useRmsMid = (gamma2_shape != nullptr);
144	
145	    // --- D-axis tiling (must compute BEFORE core mapping) ---
146	    const uint32_t alignElem = HOST_D_TILE_ALIGN_ELEM;
147	    uint32_t dimTile = D;
148	    if (dimTile > HOST_D_TILE_MAX) {
149	        dimTile = HOST_D_TILE_MAX;
150	    }
151	    dimTile = (dimTile / alignElem) * alignElem;
152	    if (dimTile == 0) dimTile = alignElem;
153	
154	    uint32_t lastDimTile = D % dimTile;
155	    uint32_t dimLoop = D / dimTile + (lastDimTile ? 1 : 0);
156	
157	    // --- [R9] Core mapping: dual-core N-split for dimLoop<=2 ---
158	    uint32_t coresPerToken = 1;
159	    if (N >= HOST_DUAL_CORE_COUNT && dimLoop <= HOST_DUAL_CORE_COUNT 
160	        && totalTokens <= (coreNumAiv / HOST_DUAL_CORE_COUNT)) {
161	        coresPerToken = HOST_DUAL_CORE_COUNT;
162	    }
163	    uint32_t myHeadCount = N / coresPerToken;
164	
165	    uint32_t logicalTokens = totalTokens * coresPerToken;
166	    uint32_t usedCoreNum = std::min(logicalTokens, coreNumAiv);
167	
168	    // Ensure core count is multiple of coresPerToken
169	    if (coresPerToken == HOST_DUAL_CORE_COUNT) {
170	        usedCoreNum = (usedCoreNum / HOST_DUAL_CORE_COUNT) * HOST_DUAL_CORE_COUNT;
171	        if (usedCoreNum == 0) usedCoreNum = HOST_DUAL_CORE_COUNT;
172	    }
173	
174	    // Token distribution
175	    uint32_t numUnits = usedCoreNum / coresPerToken;
176	    if (numUnits == 0) {
177	        numUnits = 1;
178	        usedCoreNum = coresPerToken;
179	    }
180	
181	    uint32_t rowsPerCore = totalTokens / numUnits;
182	    uint32_t remainTokens = totalTokens % numUnits;
183	    uint32_t rowsPerCoreSp = rowsPerCore + 1;
184	    uint32_t blockPivot = remainTokens;
185	
186	    // --- Fill tiling data ---
187	    AiInfraMhcSandwichNormPostPreonlyTilingData tiling;
188	    tiling.set_totalTokens(totalTokens);
189	    tiling.set_headCount(N);
190	    tiling.set_embedDim(D);
191	    tiling.set_usedCoreNum(usedCoreNum);
192	    tiling.set_rowsPerCore(rowsPerCore);
193	    tiling.set_rowsPerCoreSp(rowsPerCoreSp);
194	    tiling.set_blockPivot(blockPivot);
195	    tiling.set_dimTile(dimTile);
196	    tiling.set_dimLoop(dimLoop);
197	    tiling.set_lastDimTile(lastDimTile);
198	    tiling.set_phiRows(phiRows);
199	    tiling.set_phiCols(phiCols);
200	    tiling.set_normEps(normEps);
201	    tiling.set_hcEps(hcEps);
202	    tiling.set_invD(1.0F / static_cast<float>(D));
203	    tiling.set_invK(1.0F / static_cast<float>(N * D));
204	    tiling.set_useRmsMid(useRmsMid ? 1U : 0U);
205	    tiling.set_coresPerToken(coresPerToken);
206	    tiling.set_myHeadCount(myHeadCount);
207	    tiling.set_maxTokensPerPair(rowsPerCoreSp);  // max tokens any pair processes
208	    tiling.set_returnHInF32(static_cast<int8_t>(returnHInF32)); 
209	
210	    // --- Workspace sizing (also determines sync region start offset) ---
211	    // Dual-core: per pair = 16 + N*D floats (sync blocks + x2 data from both cores)
212	    // Single-core: per core = (N+1)*D floats
213	    size_t pairWsFloats = HOST_WS_HIN_BASE + (size_t)HOST_N_MAX * HOST_D_MAX;
214	    size_t singleWsFloats = (size_t)(HOST_N_MAX + 1) * HOST_D_MAX;
215	    size_t wsPerUnit = std::max(pairWsFloats, singleWsFloats);
216	    size_t dataWsBytes = (size_t)coreNumAiv * wsPerUnit * sizeof(float);
217	    // Cross-core sync region comes right after the data region
218	    size_t syncWsBytes = (size_t)coreNumAiv * HOST_WS_SYNC_BLOCK * HOST_WS_NUM_EVENTS * sizeof(int32_t);
219	    size_t sysWsBytes = ascendcPlatform.GetLibApiWorkSpaceSize();
220	    size_t totalWsBytes = sysWsBytes + dataWsBytes + syncWsBytes;
221	    if (totalWsBytes < HOST_MIN_WORKSPACE) {
222	        totalWsBytes = HOST_MIN_WORKSPACE;
223	    }
224	    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
225	    if (currentWorkspace == nullptr) {
226	        OPS_LOG_E("AiInfraMhcSandwichNormPostPreonly",
227	                  "GetWorkspaceSizes is nullptr");
228	        return ge::GRAPH_FAILED;
229	    }
230	    currentWorkspace[0] = totalWsBytes;
231	
232	    // Tell kernel where the sync region starts (float offset from workspace base).
233	    // Matches dataWsBytes/sizeof(float) exactly so kernel writes sync flags
234	    // into the region host reserved — not into the middle of the data region.
235	    // Previously kernel computed this itself from runtime `usedCoreNum * wsPerUnit_runtime`,
236	    // which only worked because usedCoreNum << coreNumAiv left unused data slots.
237	    tiling.set_syncGmOffsetFloats(static_cast<uint32_t>(dataWsBytes / sizeof(float)));
238	
239	    // --- Emit tiling buffer ---
240	    context->SetBlockDim(usedCoreNum);
241	    context->SetTilingKey(0);
242	    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
243	                        context->GetRawTilingData()->GetCapacity());
244	    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());
245	
246	    OP_LOGD(context->GetNodeName(), "returnHInF32:  %s", (returnHInF32 ? "true" : "false"));
247	    return ge::GRAPH_SUCCESS;
248	}
