11	// ========================================================================
12	// mhc_sandwich_norm_post_preonly_singlecore.h — single-core fallback (dimLoop>2 or N<2)
13	// v2: QuantizeRoundTrip at stage boundaries, N*D RMSNorm_mid, ReduceSumPrecise
14	// ========================================================================
15	#ifndef AI_INFRA_MHC_SANDWICH_NORM_POST_PREONLY_SINGLECORE_H_
16	#define AI_INFRA_MHC_SANDWICH_NORM_POST_PREONLY_SINGLECORE_H_
17	
18	// =================================================================
19	//  ProcessToken: single-core entry point
20	// =================================================================
21	template<typename T>
22	__aicore__ __attribute__((noinline)) void
23	KernelAiInfraMhcSandwichNormPostPreonly<T>::Apply2BatchResidualAxpyTail(
24	    uint64_t rBaseTile, uint32_t tD,
25	    const float (&combVals)[N_MAX * N_MAX])
26	{
27	    constexpr uint32_t RB = 2;
28	    const uint32_t N = N_, D = D_;
29	    LocalTensor<float> x2 = bufX2Fp32_.Get<float>();
30	
31	    // Batch 0: DeQue + Cast (V)
32	    {
33	        LocalTensor<T> resBf16 = bufResidualBf16_.DeQue<T>();
34	        LocalTensor<float> resFp32 = bufResFp32_.Get<float>();
35	        for (uint32_t n = 0; n < RB; ++n)
36	            Cast(resFp32[n * dimTile_], resBf16[n * dimTile_], RoundMode::CAST_NONE, tD);
37	        PipeBarrier<PIPE_V>();
38	        bufResidualBf16_.FreeTensor(resBf16);
39	    }
40	
41	    // Batch 1: start MTE2 for heads [RB, 2*RB) (overlaps with axpy below)
42	    {
43	        LocalTensor<T> resBf16 = bufResidualBf16_.AllocTensor<T>();
44	        for (uint32_t n = 0; n < RB; ++n)
45	            DataCopy(resBf16[n * dimTile_],
46	                     residualGm_[rBaseTile + (uint64_t)(n + RB) * D], tD);
47	        bufResidualBf16_.EnQue(resBf16);
48	    }
49	
50	    // x2 += combVals[0..RB-1] * res[0..RB-1] (V — MTE2 for batch 1 in flight)
51	    {
52	        LocalTensor<float> resFp32 = bufResFp32_.Get<float>();
53	        for (uint32_t j = 0; j < RB; ++j)
54	            for (uint32_t h = 0; h < N; ++h)
55	                Axpy(x2[h * dimTile_], resFp32[j * dimTile_],
56	                     combVals[j * N + h], tD);
57	    }
58	
59	    // Batch 1: DeQue + Cast (V)
60	    {
61	        LocalTensor<T> resBf16 = bufResidualBf16_.DeQue<T>();
62	        LocalTensor<float> resFp32 = bufResFp32_.Get<float>();
63	        for (uint32_t n = 0; n < RB; ++n)
64	            Cast(resFp32[n * dimTile_], resBf16[n * dimTile_], RoundMode::CAST_NONE, tD);
65	        PipeBarrier<PIPE_V>();
66	        bufResidualBf16_.FreeTensor(resBf16);
67	    }
68	
69	    // x2 += combVals[RB..2*RB-1] * res[0..RB-1] (V)
70	    {
71	        LocalTensor<float> resFp32 = bufResFp32_.Get<float>();
72	        for (uint32_t j = 0; j < RB; ++j)
73	            for (uint32_t h = 0; h < N; ++h)
74	                Axpy(x2[h * dimTile_], resFp32[j * dimTile_],
75	                     combVals[(j + RB) * N + h], tD);
76	    }
77	    PipeBarrier<PIPE_V>();
78	}
79	
80	template<typename T>
81	__aicore__ inline void KernelAiInfraMhcSandwichNormPostPreonly<T>::ProcessToken(uint32_t token)
82	{
83	    const uint32_t D = D_, N = N_;
84	    float postVals[N_MAX], combVals[N_MAX * N_MAX];
85	    float xHatVals[N_MAX], gate[N_MAX];
86	    float sumSqPre = 0.0f, sumSq1 = 0.0f;
87	    for (uint32_t i = 0; i < N; ++i) { xHatVals[i] = 0.0f; }
88	
89	    LoadTokenWeights(token, postVals, combVals);
90	
91	    if (dimLoop_ > 1) {
92	        uint32_t tD0 = GetTileD(0);
93	        LoadGammaInto(bufGamma0Fp32_.Get<float>(), gamma0Gm_, 0, tD0);
94	        LoadGammaInto(bufGamma1Fp32_.Get<float>(), gamma1Gm_, 0, tD0);
95	
96	        SetFlag<HardEvent::MTE2_V>(evtMte2toV_);
97	        WaitFlag<HardEvent::MTE2_V>(evtMte2toV_);
98	    }
99	
100	    if (dimLoop_ == 1)
101	        PhaseAB_SingleTile(token, postVals, combVals, xHatVals, sumSqPre);
102	    else
103	        PhaseAB_MultiTile(token, postVals, combVals, xHatVals, sumSqPre);
104	
105	    ComputeGateValues(sumSqPre, xHatVals, gate);
106	    PhaseC_HInAndX2Output(token, gate, sumSq1);
107	
108	    float invRms1 = ComputeInvRms(sumSq1, invD_);
109	    PhaseD_RmsNorm1Output(token, invRms1);
110	}
111	
112	// =================================================================
113	//  PhaseAB_SingleTile
114	// =================================================================
115	template<typename T>
116	__aicore__ inline void KernelAiInfraMhcSandwichNormPostPreonly<T>::PhaseAB_SingleTile(
117	    uint32_t token,
118	    const float (&postVals)[N_MAX], const float (&combVals)[N_MAX * N_MAX],
119	    float (&xHatVals)[N_MAX], float &sumSqPre)
120	{
121	    const uint32_t N = N_, D = D_;
122	    uint32_t tD = dimTile_;
123	    const uint64_t rBase = (uint64_t)token * N * D;
124	    LoadHOutAndCast((uint64_t)token * D, tD);
125	
126	    {
127	        LocalTensor<T> resBf16 = bufResidualBf16_.AllocTensor<T>();
128	        constexpr uint32_t RB = 2;  // residual batch size: 2 heads/batch
129	        for (uint32_t n = 0; n < RB; ++n)
130	            DataCopy(resBf16[n * dimTile_], residualGm_[rBase + (uint64_t)n * D], tD);
131	        bufResidualBf16_.EnQue(resBf16);
132	    }
133	
134	    LocalTensor<float> hOutFp32 = bufHOutFp32_.Get<float>();
135	    float invRms0 = ComputeInvRms(ReduceSumSq(hOutFp32, tD), invD_);
136	    ApplyScaleAndGamma(hOutFp32, invRms0, bufGamma0Fp32_.Get<float>(), tD);
137	    // Stage 1 boundary: x1 → dtype → fp32
138	    QuantizeRoundTrip(hOutFp32, tD);
139	
140	    // x2 init: x2[h] = postVals[h] * hOutNorm  (V)
141	    {
142	        LocalTensor<float> x2 = bufX2Fp32_.Get<float>();
143	        for (uint32_t h = 0; h < N; ++h)
144	            Muls(x2[h * dimTile_], hOutFp32, postVals[h], tD);
145	    }
146	
147	    // [perf] 2-batch residual axpy tail (shared with PhaseAB_MultiTile via
148	    // noinline helper).  See class declaration for full pre-/post-conditions.
149	    Apply2BatchResidualAxpyTail(rBase, tD, combVals);
150	
151	    // Stage 2 boundary: x2 → dtype → fp32
152	    {
153	        LocalTensor<float> x2Tmp = bufX2Fp32_.Get<float>();
154	        for (uint32_t n = 0; n < N; ++n)
155	            QuantizeRoundTrip(x2Tmp[n * dimTile_], tD);
156	    }
157	
158	    if (useRmsMid_) {
159	        ApplyRmsNormMidSingleTile(tD);
160	        // Stage 2.5 boundary: x2 → dtype → fp32
161	        LocalTensor<float> x2Tmp = bufX2Fp32_.Get<float>();
162	        for (uint32_t n = 0; n < N; ++n)
163	            QuantizeRoundTrip(x2Tmp[n * dimTile_], tD);
164	    }
165	
166	    // sumSqPre
167	    LocalTensor<float> x2Fp32 = bufX2Fp32_.Get<float>();
168	    LocalTensor<float> outFp32 = bufOutFp32_.Get<float>();
169	    LocalTensor<float> sqBuf = bufSqFp32_.Get<float>();
170	
171	    Mul(outFp32, x2Fp32, x2Fp32, tD); PipeBarrier<PIPE_V>();
172	    for (uint32_t n = 1; n < N; ++n) {
173	        Mul(sqBuf, x2Fp32[n*dimTile_], x2Fp32[n*dimTile_], tD); PipeBarrier<PIPE_V>();
174	        Add(outFp32, outFp32, sqBuf, tD); PipeBarrier<PIPE_V>();
175	    }
176	    sumSqPre += ReduceSumPrecise(outFp32, tD);
177	
178	    // phi matmul
179	    DataCopyExtParams cpP = {1, 0, 0, 0, 0};
180	    cpP.blockLen = tD * sizeof(float);
181	    DataCopyPadExtParams<float> cpPad = {true, 0, 0, 0};
182	
183	    for (uint32_t o = 0; o < phiRows_; ++o) {
184	        LocalTensor<float> phiFp32 = bufPhiFp32_.AllocTensor<float>();
185	        DataCopyPad(phiFp32, phiGm_[(uint64_t)o * phiCols_], cpP, cpPad);
186	        bufPhiFp32_.EnQue(phiFp32);
187	        phiFp32 = bufPhiFp32_.DeQue<float>();
188	        Mul(outFp32, x2Fp32, phiFp32, tD); PipeBarrier<PIPE_V>();
189	        bufPhiFp32_.FreeTensor(phiFp32);
190	
191	        for (uint32_t n = 1; n < N; ++n) {
192	            uint64_t phiOff = (uint64_t)o * phiCols_ + (uint64_t)n * D;
193	            phiFp32 = bufPhiFp32_.AllocTensor<float>();
194	            DataCopyPad(phiFp32, phiGm_[phiOff], cpP, cpPad);
195	            bufPhiFp32_.EnQue(phiFp32);
196	            phiFp32 = bufPhiFp32_.DeQue<float>();
197	            Mul(sqBuf, x2Fp32[n*dimTile_], phiFp32, tD); PipeBarrier<PIPE_V>();
198	            Add(outFp32, outFp32, sqBuf, tD); PipeBarrier<PIPE_V>();
199	            bufPhiFp32_.FreeTensor(phiFp32);
200	        }
201	        xHatVals[o] += ReduceSumPrecise(outFp32, tD);
202	    }
203	}
204	
205	// =================================================================
206	//  PhaseAB_MultiTile (single-core, dimLoop>2 fallback)
207	// =================================================================
208	template<typename T>
209	__aicore__ inline void KernelAiInfraMhcSandwichNormPostPreonly<T>::PhaseAB_MultiTile(
210	    uint32_t token,
211	    const float (&postVals)[N_MAX], const float (&combVals)[N_MAX * N_MAX],
212	    float (&xHatVals)[N_MAX], float &sumSqPre)
213	{
214	    const uint32_t N = N_, D = D_;
215	
216	    // Pass 1: RMSNorm_0 sum-of-squares
217	    float sumSq0 = 0.0f;
218	    for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
219	        uint32_t tD = GetTileD(tile);
220	        LoadHOutAndCast((uint64_t)token * D + tile * dimTile_, tD);
221	        sumSq0 += ReduceSumSq(bufHOutFp32_.Get<float>(), tD);
222	    }
223	    float invRms0 = ComputeInvRms(sumSq0, invD_);
224	    LocalTensor<float> gamma0Fp32 = bufGamma0Fp32_.Get<float>();
225	
226	    // Pass 2: normalize + MHC_Post + accumulate sumSqMid (total across all heads)
227	    float totalSumSqMid = 0.0f;
228	    for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
229	        uint32_t tD = GetTileD(tile), tOff = tile * dimTile_;
230	
231	        LoadHOutAndCast((uint64_t)token * D + tOff, tD);
232	        if (tile > 0) {
233	            LoadGammaInto(gamma0Fp32, gamma0Gm_, tOff, tD);
234	            SetFlag<HardEvent::MTE2_V>(evtMte2toV_);
235	            WaitFlag<HardEvent::MTE2_V>(evtMte2toV_);
236	        }
237	        ApplyScaleAndGamma(bufHOutFp32_.Get<float>(), invRms0, gamma0Fp32, tD);
238	        // Stage 1 boundary: x1 → dtype → fp32
239	        QuantizeRoundTrip(bufHOutFp32_.Get<float>(), tD);
240	
241	        // [perf] 2-batch residual loading per tile (matches PhaseAB_SingleTile):
242	        // bufResFp32_ holds 2 heads in single-core mode → load + apply in 2
243	        // batches, overlapping MTE2 (next batch) with V (axpy of current batch).
244	        const uint64_t rBaseTile = (uint64_t)token * N * D + tOff;
245	
246	        // Batch 0: kick off MTE2 for heads [0, RB) (parallel with x2 init below).
247	        {
248	            constexpr uint32_t RB = 2;
249	            LocalTensor<T> resBf16 = bufResidualBf16_.AllocTensor<T>();
250	            for (uint32_t n = 0; n < RB; ++n)
251	                DataCopy(resBf16[n * dimTile_],
252	                         residualGm_[rBaseTile + (uint64_t)n * D], tD);
253	            bufResidualBf16_.EnQue(resBf16);
254	        }
255	
256	        // x2 init: x2[h] = postVals[h] * hOutNorm  (V, overlaps with batch 0 MTE2)
257	        {
258	            LocalTensor<float> x2 = bufX2Fp32_.Get<float>();
259	            LocalTensor<float> hOut = bufHOutFp32_.Get<float>();
260	            for (uint32_t h = 0; h < N; ++h)
261	                Muls(x2[h * dimTile_], hOut, postVals[h], tD);
262	        }
263	
264	        // Shared 2-batch residual axpy tail (noinline helper, see class decl).
265	        Apply2BatchResidualAxpyTail(rBaseTile, tD, combVals);
266	
267	        // Stage 2 boundary: x2 → dtype → fp32
268	        LocalTensor<float> x2Fp32 = bufX2Fp32_.Get<float>();
269	        for (uint32_t n = 0; n < N; ++n)
270	            QuantizeRoundTrip(x2Fp32[n * dimTile_], tD);
271	
272	        if (useRmsMid_) {
273	            // Accumulate total sumSq across ALL heads for N*D RMSNorm_mid
274	            for (uint32_t n = 0; n < N; ++n)
275	                totalSumSqMid += ReduceSumSq(x2Fp32[n * dimTile_], tD);
276	            PipeBarrier<PIPE_V>();
277	        } else {
278	            sumSqPre += ComputeSumSqAllHeads(tD);
279	            ComputePhiMatmulTile(tD, tOff, xHatVals);
280	            PipeBarrier<PIPE_V>();
281	        }
282	        // Write x2 to workspace for later phases
283	        for (uint32_t n = 0; n < N; ++n) {
284	            DataCopyExtParams wp = {1, 0, 0, 0, 0};
285	            wp.blockLen = tD * sizeof(float);
286	            DataCopyPad(workspaceGm_[pairWsBase_ + (uint64_t)n * D + tOff],
287	                        x2Fp32[n * dimTile_], wp);
288	        }
289	        PipeBarrier<PIPE_ALL>();
290	    }
291	
292	    // RMSNorm_mid second pass (if enabled): single invRms over N*D
293	    if (useRmsMid_) {
294	        float invRmsMid = 1.0f / sqrt(totalSumSqMid * invK_ + normEps_);
295	
296	        for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
297	            uint32_t tD = GetTileD(tile), tOff = tile * dimTile_;
298	            LocalTensor<float> x2Fp32 = bufX2Fp32_.Get<float>();
299	            for (uint32_t n = 0; n < N; ++n) {
300	                DataCopyExtParams rp = {1, 0, 0, 0, 0};
301	                rp.blockLen = tD * sizeof(float);
302	                DataCopyPadExtParams<float> rpad = {false, 0, 0, 0};
303	                DataCopyPad(x2Fp32[n * dimTile_],
304	                            workspaceGm_[pairWsBase_ + (uint64_t)n * D + tOff], rp, rpad);
305	            }
306	            LocalTensor<float> gamma2 = bufGamma2Fp32_.Get<float>();
307	
308	            // gamma_2 is [N*D]: load gamma_2[n*D+tOff : n*D+tOff+tD] for each head
309	            for (uint32_t n = 0; n < N; ++n) {
310	                LoadGammaInto(gamma2, gamma2Gm_, n * D + tOff, tD);
311	                SetFlag<HardEvent::MTE2_V>(evtMte2toV_);
312	                WaitFlag<HardEvent::MTE2_V>(evtMte2toV_);
313	                ApplyScaleAndGamma(x2Fp32[n * dimTile_], invRmsMid, gamma2, tD);
314	                PipeBarrier<PIPE_ALL>();
315	            }
316	
317	            // Stage 2.5 boundary: x2 → dtype → fp32
318	            for (uint32_t n = 0; n < N; ++n)
319	                QuantizeRoundTrip(x2Fp32[n * dimTile_], tD);
320	
321	            sumSqPre += ComputeSumSqAllHeads(tD);
322	            ComputePhiMatmulTile(tD, tOff, xHatVals);
323	
324	            PipeBarrier<PIPE_V>();
325	            for (uint32_t n = 0; n < N; ++n) {
326	                DataCopyExtParams wp = {1, 0, 0, 0, 0};
327	                wp.blockLen = tD * sizeof(float);
328	                DataCopyPad(workspaceGm_[pairWsBase_ + (uint64_t)n * D + tOff],
329	                            x2Fp32[n * dimTile_], wp);
330	            }
331	            PipeBarrier<PIPE_ALL>();
332	        }
333	    }
334	}
335	
336	// =================================================================
337	//  PhaseC_HInAndX2Output (single-core)
338	// =================================================================
339	template<typename T>
340	__aicore__ inline void KernelAiInfraMhcSandwichNormPostPreonly<T>::PhaseC_HInAndX2Output(
341	    uint32_t token, const float (&gate)[N_MAX], float &sumSq1)
342	{
343	    const uint32_t N = N_, D = D_;
344	    bool x2InWs = (dimLoop_ > 1);
345	
346	    for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
347	        uint32_t tD = GetTileD(tile), tOff = tile * dimTile_;
348	        LocalTensor<float> x2Fp32 = bufX2Fp32_.Get<float>();
349	
350	        if (x2InWs) {
351	            for (uint32_t n = 0; n < N; ++n) {
352	                DataCopyExtParams rp = {1, 0, 0, 0, 0};
353	                rp.blockLen = tD * sizeof(float);
354	                DataCopyPadExtParams<float> rpad = {false, 0, 0, 0};
355	                DataCopyPad(x2Fp32[n * dimTile_],
356	                            workspaceGm_[pairWsBase_ + (uint64_t)n * D + tOff], rp, rpad);
357	            }
358	            PipeBarrier<PIPE_ALL>();
359	        }
360	
361	        // Write x2_out
362	        uint64_t x2OutBase = (uint64_t)token * N * D + tOff;
363	        for (uint32_t n = 0; n < N; ++n)
364	            WriteX2OutTile(x2Fp32[n * dimTile_], x2OutBase + (uint64_t)n * D, tD);
365	
366	        // Compute h_in
367	        LocalTensor<float> outFp32 = bufOutFp32_.Get<float>();
368	        Muls(outFp32, x2Fp32, gate[0], tD); PipeBarrier<PIPE_V>();
369	        for (uint32_t n = 1; n < N; ++n) {
370	            Axpy(outFp32, x2Fp32[n * dimTile_], gate[n], tD); PipeBarrier<PIPE_V>();
371	        }
372	
373	        // Stage 3 boundary: h_in → dtype → fp32
374	        QuantizeRoundTrip(outFp32, tD);
375	
376	        sumSq1 += ReduceSumSq(outFp32, tD);
377	
378	        if (dimLoop_ > 1) {
379	            PipeBarrier<PIPE_V>();
380	            DataCopyExtParams wp = {1, 0, 0, 0, 0};
381	            wp.blockLen = tD * sizeof(float);
382	            DataCopyPad(workspaceGm_[pairWsBase_ + (uint64_t)N * D + tOff], outFp32, wp);
383	            PipeBarrier<PIPE_ALL>();
384	        }
385	    }
386	}
387	
388	// =================================================================
389	//  PhaseD_RmsNorm1Output (single-core)
390	// =================================================================
391	template<typename T>
392	__aicore__ inline void KernelAiInfraMhcSandwichNormPostPreonly<T>::PhaseD_RmsNorm1Output(
393	    uint32_t token, float invRms1)
394	{
395	    const uint32_t N = N_, D = D_;
396	    LocalTensor<float> gamma1Fp32 = bufGamma1Fp32_.Get<float>();
397	
398	    for (uint32_t tile = 0; tile < dimLoop_; ++tile) {
399	        uint32_t tD = GetTileD(tile), tOff = tile * dimTile_;
400	        LocalTensor<float> outFp32 = bufOutFp32_.Get<float>();
401	
402	        if (dimLoop_ > 1) {
403	            if (tile > 0 && returnHInF32_) {
404	                PipeBarrier<PIPE_ALL>();
405	            }
406	            DataCopyExtParams rp = {1, 0, 0, 0, 0};
407	            rp.blockLen = tD * sizeof(float);
408	            DataCopyPadExtParams<float> rpad = {false, 0, 0, 0};
409	            DataCopyPad(outFp32, workspaceGm_[pairWsBase_ + (uint64_t)N * D + tOff], rp, rpad);
410	            PipeBarrier<PIPE_ALL>();
411	        }
412	        if (tile > 0) {
413	            LoadGammaInto(gamma1Fp32, gamma1Gm_, tOff, tD);
414	            SetFlag<HardEvent::MTE2_V>(evtMte2toV_);
415	            WaitFlag<HardEvent::MTE2_V>(evtMte2toV_);
416	        }
417	        ApplyScaleAndGamma(outFp32, invRms1, gamma1Fp32, tD);
418	        WriteHInPrimeTile(outFp32, (uint64_t)token * D + tOff, tD);
419	    }
420	}
421	
422	// =================================================================
423	//  Single-core building blocks
424	// =================================================================
425	template<typename T>
426	__aicore__ inline float KernelAiInfraMhcSandwichNormPostPreonly<T>::ComputeSumSqAllHeads(uint32_t tD)
427	{
428	    LocalTensor<float> x2  = bufX2Fp32_.Get<float>();
429	    LocalTensor<float> out = bufOutFp32_.Get<float>();
430	    LocalTensor<float> sq  = bufSqFp32_.Get<float>();
431	    const uint32_t N = N_;
432	
433	    Mul(out, x2, x2, tD); PipeBarrier<PIPE_V>();
434	    for (uint32_t n = 1; n < N; ++n) {
435	        Mul(sq, x2[n*dimTile_], x2[n*dimTile_], tD); PipeBarrier<PIPE_V>();
436	        Add(out, out, sq, tD); PipeBarrier<PIPE_V>();
437	    }
438	    return ReduceSumPrecise(out, tD);
439	}
440	
441	template<typename T>
442	__aicore__ inline void KernelAiInfraMhcSandwichNormPostPreonly<T>::ComputePhiMatmulTile(
443	    uint32_t tD, uint32_t tOff, float (&xHatVals)[N_MAX])
444	{
445	    LocalTensor<float> x2  = bufX2Fp32_.Get<float>();
446	    LocalTensor<float> out = bufOutFp32_.Get<float>();
447	    LocalTensor<float> sq  = bufSqFp32_.Get<float>();
448	    const uint32_t N = N_, D = D_;
449	
450	    DataCopyExtParams cpP = {1, 0, 0, 0, 0};
451	    cpP.blockLen = tD * sizeof(float);
452	    DataCopyPadExtParams<float> cpPad = {true, 0, 0, 0};
453	
454	    for (uint32_t o = 0; o < phiRows_; ++o) {
455	        {
456	            LocalTensor<float> phi = bufPhiFp32_.AllocTensor<float>();
457	            DataCopyPad(phi, phiGm_[(uint64_t)o * phiCols_ + tOff], cpP, cpPad);
458	            bufPhiFp32_.EnQue(phi); phi = bufPhiFp32_.DeQue<float>();
459	            Mul(out, x2, phi, tD); PipeBarrier<PIPE_V>();
460	            bufPhiFp32_.FreeTensor(phi);
461	        }
462	        for (uint32_t n = 1; n < N; ++n) {
463	            uint64_t phiOff = (uint64_t)o * phiCols_ + (uint64_t)n * D + tOff;
464	            LocalTensor<float> phi = bufPhiFp32_.AllocTensor<float>();
465	            DataCopyPad(phi, phiGm_[phiOff], cpP, cpPad);
466	            bufPhiFp32_.EnQue(phi); phi = bufPhiFp32_.DeQue<float>();
467	            Mul(sq, x2[n*dimTile_], phi, tD); PipeBarrier<PIPE_V>();
468	            Add(out, out, sq, tD); PipeBarrier<PIPE_V>();
469	            bufPhiFp32_.FreeTensor(phi);
470	        }
471	        xHatVals[o] += ReduceSumPrecise(out, tD);
472	    }
473	}
474	
475	template<typename T>
476	__aicore__ inline void KernelAiInfraMhcSandwichNormPostPreonly<T>::ApplyRmsNormMidSingleTile(
477	    uint32_t tD)
478	{
479	    LocalTensor<float> x2 = bufX2Fp32_.Get<float>();
480	    const uint32_t N = N_, D = D_;
481	
482	    // Compute total sumSq across ALL N heads (N*D RMSNorm)
483	    float totalSumSqMid = 0.0f;
484	    for (uint32_t n = 0; n < N; ++n)
485	        totalSumSqMid += ReduceSumSq(x2[n * dimTile_], tD);
486	
487	    // Single invRms using invK_ = 1/(N*D)
488	    float invRmsMid = 1.0f / sqrt(totalSumSqMid * invK_ + normEps_);
489	    PipeBarrier<PIPE_ALL>();
490	
491	    // gamma_2 is [N*D]: load gamma_2[n*D : (n+1)*D] for each head
492	    LocalTensor<float> gamma2 = bufGamma2Fp32_.Get<float>();
493	    for (uint32_t n = 0; n < N; ++n) {
494	        LoadGammaInto(gamma2, gamma2Gm_, n * D, tD);
495	        SetFlag<HardEvent::MTE2_V>(evtMte2toV_);
496	        WaitFlag<HardEvent::MTE2_V>(evtMte2toV_);
497	        ApplyScaleAndGamma(x2[n * dimTile_], invRmsMid, gamma2, tD);
498	        PipeBarrier<PIPE_ALL>();
499	    }
500	}
