20	    float (&postVals)[N_MAX], float (&combVals)[N_MAX * N_MAX])
21	{
22	    const uint32_t N = N_;
23	    LocalTensor<float> postCombUb = bufPostComb_.Get<float>();
24	    LocalTensor<float> hPostUb = postCombUb;
25	    LocalTensor<float> hResUb = postCombUb[ALIGN8];  // h_post[N] aligned to 8 elements
26	    {
27	        DataCopyExtParams pp = {1, 0, 0, 0, 0};
28	        pp.blockLen = N * sizeof(float);
29	        DataCopyPadExtParams<float> pad = {true, 0, 0, 0};
30	        DataCopyPad(hPostUb, hPostGm_[(uint64_t)token * N], pp, pad);
31	
32	        DataCopyExtParams cp = {1, 0, 0, 0, 0};
33	        cp.blockLen = N * N * sizeof(float);
34	        DataCopyPadExtParams<float> cpad = {true, 0, 0, 0};
35	        DataCopyPad(hResUb, hResGm_[(uint64_t)token * N * N], cp, cpad);
36	    }
37	    PipeBarrier<PIPE_ALL>();
38	    for (uint32_t i = 0; i < N; ++i) postVals[i] = hPostUb.GetValue(i);
39	    for (uint32_t i = 0; i < N * N; ++i) combVals[i] = hResUb.GetValue(i);
40	}
41	
42	/// Load h_out[token, tOff:tOff+tD] bf16 → bufHOutFp32_ fp32
43	__aicore__ inline void LoadHOutAndCast(uint64_t gmOffset, uint32_t tD)
44	{
45	    LocalTensor<T> hBf16 = bufHOutBf16_.AllocTensor<T>();
46	    DataCopy(hBf16, hOutGm_[gmOffset], tD);
47	    bufHOutBf16_.EnQue(hBf16);
48	    hBf16 = bufHOutBf16_.DeQue<T>();
49	    Cast(bufHOutFp32_.Get<float>(), hBf16, RoundMode::CAST_NONE, tD);
50	    PipeBarrier<PIPE_V>();
51	    bufHOutBf16_.FreeTensor(hBf16);
52	}
53	
54	/// Load residual[token, 0:N, tOff:tOff+tD] bf16 → bufResFp32_ fp32
55	__aicore__ inline void LoadResidualAndCast(uint64_t gmBaseOffset, uint32_t tD)
56	{
57	    const uint32_t N = N_;
58	    LocalTensor<T> resBf16 = bufResidualBf16_.AllocTensor<T>();
59	    for (uint32_t n = 0; n < N; ++n)
60	        DataCopy(resBf16[n * dimTile_],
61	                 residualGm_[gmBaseOffset + (uint64_t)n * D_], tD);
62	    bufResidualBf16_.EnQue(resBf16);
63	    resBf16 = bufResidualBf16_.DeQue<T>();
64	    LocalTensor<float> resFp32 = bufResFp32_.Get<float>();
65	    for (uint32_t n = 0; n < N; ++n)
66	        Cast(resFp32[n * dimTile_], resBf16[n * dimTile_],
67	             RoundMode::CAST_NONE, tD);
68	    PipeBarrier<PIPE_V>();
69	    bufResidualBf16_.FreeTensor(resBf16);
70	}
71	
72	/// Load a gamma vector into the specified buffer for tile [tOff, tOff+tD)
73	__aicore__ inline void LoadGammaInto(LocalTensor<float> dst,
74	    GlobalTensor<float>& src, uint32_t tOff, uint32_t tD)
75	{
76	    DataCopyExtParams gP = {1, 0, 0, 0, 0};
77	    gP.blockLen = tD * sizeof(float);
78	    DataCopyPadExtParams<float> gPad = {false, 0, 0, 0};
79	    DataCopyPad(dst, src[tOff], gP, gPad);
80	}
81	
82	// ---- RMSNorm primitives ----
83	
84	/// High-precision ReduceSum using binary tree accumulation (Pattern::Reduce::AR)
85	__aicore__ inline float ReduceSumPrecise(LocalTensor<float> src, uint32_t tD)
86	{
87	    LocalTensor<float> scBuf = bufScalar_.Get<float>();
88	    constexpr uint32_t REDUCE_ALIGN = 16;  // ReduceSum requires 16-element alignment
89	    uint32_t tDAligned = (tD + REDUCE_ALIGN - 1) / REDUCE_ALIGN * REDUCE_ALIGN;
90	    uint32_t srcShape[2] = {1, tDAligned};
91	    ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(scBuf, src, srcShape, true);
92	    PipeBarrier<PIPE_V>();
93	    return scBuf.GetValue(0);
94	}
95	
96	/// Compute sum-of-squares using ReduceSumPrecise
97	__aicore__ inline float ReduceSumSq(LocalTensor<float> src, uint32_t tD)
98	{
99	    LocalTensor<float> sqBuf = bufSqFp32_.Get<float>();
100	    Mul(sqBuf, src, src, tD);
101	    PipeBarrier<PIPE_V>();
102	    return ReduceSumPrecise(sqBuf, tD);
103	}
104	
105	/// 1/sqrt(sumSq * invCount + eps) — scalar precision
106	__aicore__ inline __attribute__((always_inline)) float ComputeInvRms(
107	    float sumSq, float invCount)
108	{
109	    return 1.0f / sqrt(sumSq * invCount + normEps_);
110	}
111	
112	/// Apply in-place: buf = buf * scalar, then buf = buf * gamma
113	__aicore__ inline void ApplyScaleAndGamma(LocalTensor<float> buf,
114	    float scale, LocalTensor<float> gamma, uint32_t tD)
115	{
116	    Muls(buf, buf, scale, tD);
117	    PipeBarrier<PIPE_V>();
118	    Mul(buf, buf, gamma, tD);
119	    PipeBarrier<PIPE_V>();
120	}
121	
122	// ---- MHC_Post ----
123	
124	/// Compute x2 for myN heads into bufX2Fp32_:
125	///   x2[hi] = postVals[hStart+hi] * hOutFp32 + sum_j(combVals[j,h] * resFp32[j])
126	__aicore__ inline void ComputeX2MyHeads(
127	    const float (&postVals)[N_MAX], const float (&combVals)[N_MAX * N_MAX],
128	    uint32_t tD)
129	{
130	    const uint32_t N = N_;
131	    const uint32_t myN = myHeadCount_;
132	    const uint32_t hStart = headStart_;
133	    LocalTensor<float> x2Fp32  = bufX2Fp32_.Get<float>();
134	    LocalTensor<float> hOutFp32 = bufHOutFp32_.Get<float>();
135	    LocalTensor<float> resFp32  = bufResFp32_.Get<float>();
136	
137	    for (uint32_t hi = 0; hi < myN; ++hi)
138	        Muls(x2Fp32[hi * dimTile_], hOutFp32, postVals[hStart + hi], tD);
139	    PipeBarrier<PIPE_V>();
140	
141	    for (uint32_t j = 0; j < N; ++j) {
142	        for (uint32_t hi = 0; hi < myN; ++hi)
143	            Axpy(x2Fp32[hi * dimTile_], resFp32[j * dimTile_],
144	                 combVals[j * N + (hStart + hi)], tD);
145	        PipeBarrier<PIPE_V>();
146	    }
147	}
148	
149	/// Compute x2 for ALL N heads into bufX2Fp32_ (single-core path, batched)
150	__aicore__ inline void ComputeX2AllHeadsBatched(
151	    const float (&postVals)[N_MAX], const float (&combVals)[N_MAX * N_MAX],
152	    uint32_t tD)
153	{
154	    const uint32_t N = N_;
155	    LocalTensor<float> x2     = bufX2Fp32_.Get<float>();
156	    LocalTensor<float> hOut   = bufHOutFp32_.Get<float>();
157	    LocalTensor<float> res    = bufResFp32_.Get<float>();
158	
159	    for (uint32_t h = 0; h < N; ++h)
160	        Muls(x2[h * dimTile_], hOut, postVals[h], tD);
161	    PipeBarrier<PIPE_V>();
162	    for (uint32_t j = 0; j < N; ++j) {
163	        for (uint32_t h = 0; h < N; ++h)
164	            Axpy(x2[h * dimTile_], res[j * dimTile_], combVals[j * N + h], tD);
165	        PipeBarrier<PIPE_V>();
166	    }
167	}
168	
169	/// Compute x2 for ALL N heads, per-head serialized (multi-tile single-core)
170	__aicore__ inline void ComputeX2AllHeadsSerial(
171	    const float (&postVals)[N_MAX], const float (&combVals)[N_MAX * N_MAX],
172	    uint32_t tD)
173	{
174	    const uint32_t N = N_;
175	    LocalTensor<float> x2   = bufX2Fp32_.Get<float>();
176	    LocalTensor<float> hOut = bufHOutFp32_.Get<float>();
177	    LocalTensor<float> res  = bufResFp32_.Get<float>();
178	
179	    for (uint32_t h = 0; h < N; ++h) {
180	        Muls(x2[h * dimTile_], hOut, postVals[h], tD);
181	        PipeBarrier<PIPE_V>();
182	        for (uint32_t j = 0; j < N; ++j) {
183	            Axpy(x2[h * dimTile_], res[j * dimTile_], combVals[j * N + h], tD);
184	            PipeBarrier<PIPE_V>();
185	        }
186	    }
187	}
188	
189	// ---- Gate computation ----
190	
191	/// Compute gate[0..N-1] from xHatVals (after invRmsPre scaling):
192	///   gate[i] = sigmoid(alpha0 * xHat[i] + bias[i]) + hcEps
193	__aicore__ inline void ComputeGateValues(
194	    float totalSumSqPre, float (&xHatVals)[N_MAX], float (&gate)[N_MAX])
195	{
196	    const uint32_t N = N_;
197	    float invRmsPre = ComputeInvRms(totalSumSqPre, invK_);
198	    for (uint32_t o = 0; o < phiRows_; ++o) xHatVals[o] *= invRmsPre;
199	
200	    LocalTensor<float> scBuf = bufScalar_.Get<float>();
201	    for (uint32_t i = 0; i < N; ++i)
202	        scBuf.SetValue(i, -(alpha0_ * xHatVals[i] + biasCache_[i]));
203	    for (uint32_t i = N; i < ALIGN8; ++i) scBuf.SetValue(i, 0.0f);
204	    PipeBarrier<PIPE_V>();
205	    Exp(scBuf, scBuf, EXP_DIV_ELEM);
206	    PipeBarrier<PIPE_V>();
207	    Adds(scBuf, scBuf, 1.0f, EXP_DIV_ELEM);           // 1 + exp(-z)
208	    PipeBarrier<PIPE_V>();
209	    LocalTensor<float> onesBuf = scBuf[EXP_DIV_ELEM * 2];
210	    Duplicate(onesBuf, 1.0f, EXP_DIV_ELEM);
211	    PipeBarrier<PIPE_V>();
212	    LocalTensor<float> gateBuf = scBuf[EXP_DIV_ELEM];
213	    Div(gateBuf, onesBuf, scBuf, EXP_DIV_ELEM);        // 1 / (1+exp(-z))
214	    PipeBarrier<PIPE_V>();
215	    Adds(gateBuf, gateBuf, hcEps_, EXP_DIV_ELEM);      // + hcEps
216	    PipeBarrier<PIPE_V>();
217	    for (uint32_t i = 0; i < N; ++i) gate[i] = gateBuf.GetValue(i);
218	}
