#include "ai_infra_mhc_sandwich_norm_post_preonly.h"
#include "aclnn_kernels/common/op_error_check.h"
#include "opdev/make_op_executor.h"
#include "opdev/op_def.h"
#include "opdev/op_dfx.h"
#include "opdev/op_executor.h"
#include "opdev/op_log.h"

using namespace op;

namespace l0op {

OP_TYPE_REGISTER(AiInfraMhcSandwichNormPostPreonly);

bool AiInfraMhcSandwichNormPostPreonly(const aclTensor *hOut, const aclTensor *residual, const aclTensor *hPost,
                                       const aclTensor *hRes, const aclTensor *phi, const aclTensor *alpha0,
                                       const aclTensor *bias, const aclTensor *gamma0, const aclTensor *gamma1,
                                       const aclTensor *gamma2Optional, double normEps, double hcEps, bool returnHInF32,
                                       const aclTensor *hInPrime, const aclTensor *x2Out, const aclTensor *hInF32,
                                       aclOpExecutor *executor)
{
    if (returnHInF32 == false) {
        hInF32 = executor->AllocTensor(hPost->GetDataType(), Format::FORMAT_ND, Format::FORMAT_ND);
    }

    L0_DFX(AiInfraMhcSandwichNormPostPreonly, hOut, residual, hPost, hRes, phi, alpha0, bias, gamma0, gamma1,
           gamma2Optional, hInPrime, x2Out, hInF32);
    auto ret = ADD_TO_LAUNCHER_LIST_AICORE(
        AiInfraMhcSandwichNormPostPreonly,
        OP_INPUT(hOut, residual, hPost, hRes, phi, alpha0, bias, gamma0, gamma1, gamma2Optional),
        OP_OUTPUT(hInPrime, x2Out, hInF32),
        OP_ATTR(static_cast<float>(normEps), static_cast<float>(hcEps), returnHInF32));
    OP_CHECK_ADD_TO_LAUNCHER_LIST_AICORE(ret != ACLNN_SUCCESS, return false,
                                         "AiInfraMhcSandwichNormPostPreonly AddToLauncherList failed.");

    return true;
}

} // namespace l0op

