    EXEC_NPU_CMD_V1(aclnnAiInfraMhcSandwichNormPostPreonly, h_out, residual, h_post, h_res, phi, alpha_0, bias, gamma_0,
                    gamma_1, gamma_2, norm_eps, hc_eps, h_in_prime, x_2_out);

    return {h_in_prime, x_2_out};
}

